const NOTE_ORGANIZE_CLIENT_TIMEOUT_MS = 1_800_000;
const NOTE_ORGANIZE_CLIENT_TIMEOUT_MINUTES = Math.round(NOTE_ORGANIZE_CLIENT_TIMEOUT_MS / 60_000);
const NOTE_ORGANIZE_GATEWAY_TIMEOUT_MS = 540_000;
const NOTE_ORGANIZE_TRANSPORT_MAX_ATTEMPTS = 6;
const NOTE_ORGANIZE_BACKEND_RECOVERY_WAIT_MS = 15 * 60_000;
