class ApiError extends Error {
  details: any;

  constructor(message: string, details: any) {
    super(message);
    this.name = "ApiError";
    this.details = details;
  }
}

async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const headers: Record<string, string> = { ...(init?.headers as Record<string, string> | undefined) };
  if (init?.body !== undefined && !headers["Content-Type"]) headers["Content-Type"] = "application/json";
  let res: Response;
  try {
    res = await fetch(path, {
      ...init,
      headers
    });
  } catch (err) {
    if (err instanceof Error && err.name === "AbortError") {
      throw new Error(`请求已取消或超过 ${NOTE_ORGANIZE_CLIENT_TIMEOUT_MINUTES} 分钟等待上限；若已创建后台整理任务，Worker 运维与 Gateway/MiniMax 重试会继续记录状态。`);
    }
    throw new Error(toDisplayError(err instanceof Error ? err.message : String(err)));
  }
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data?.ok === false) {
    const details = [
      data.message || data.error || res.statusText,
      data.reasonLabel,
      data.stage && `stage=${data.stage}`,
      data.reason && `reason=${data.reason}`,
      data.debugReportPath && `debugReport=${data.debugReportPath}`,
      data.advice,
    ].filter(Boolean).join("；");
    throw new ApiError(toDisplayError(details), data);
  }
  return data as T;
}

function apiErrorDetails(err: unknown) {
  return err instanceof ApiError ? err.details : null;
}

function requestTimeoutSignal(timeoutMs: number) {
  const timeoutFactory = (AbortSignal as unknown as { timeout?: (ms: number) => AbortSignal }).timeout;
  if (typeof timeoutFactory === "function") return timeoutFactory(timeoutMs);
  const controller = new AbortController();
  window.setTimeout(() => controller.abort(), timeoutMs);
  return controller.signal;
}

function toDisplayError(input: unknown) {
  const raw = String(input || "请求失败");
  if (/failed to fetch|load failed|networkerror|network error|fetch failed/i.test(raw)) return backendUnavailableText;
  return raw
    .replace(/Command failed:\s*openclaw-cn\s+gateway\s+call[\s\S]*/gi, "OpenClaw Gateway RPC failed")
    .replace(/openclaw-cn\s+gateway\s+call\s+[^\n\r]*/gi, "OpenClaw Gateway RPC failed")
    .replace(/--params\s+\{[\s\S]*?\}\s+--timeout/gi, "--params [redacted] --timeout")
    .slice(0, 800);
}

function toDateRouteSegment(value: string) {
  const raw = String(value || "").trim();
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return "";
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) return "";
  if (month < 1 || month > 12 || day < 1 || day > 31) return "";
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() + 1 !== month || date.getDate() !== day) return "";
  return `${match[1]}-${match[2]}-${match[3]}`;
}

function normalizeAssistantRouteDate(value: string | undefined) {
  return toDateRouteSegment(value || "") || formatLocalDate(new Date());
}

function normalizeAppRouteFromPath(): AppRoute {
  if (typeof window === "undefined") return { page: "system" };
  const cleaned = window.location.pathname.replace(/^\/+/, "").replace(/\/+$/, "");
  const segments = cleaned ? cleaned.split("/") : [];
  const slug = segments[0] || "agent";
  const nextDate = toDateRouteSegment(segments[1] || "");

  if (slug === "tasks" || slug === "command") return { page: "tasks" };
  if (slug === "agent" || slug === "agents" || slug === "agent-workbench") return { page: "agent" };
  if (slug === "overview") return { page: "overview" };
  if (slug === "mobile") return { page: "mobile" };
  if (slug === "research") return { page: "research" };
  if (slug === "opc") return { page: "opc" };
  if (["chat", "knowledge", "graph", "assistant", "projects", "system", "delivery"].includes(slug)) {
    return { page: slug as Page, assistantDate: slug === "assistant" ? nextDate : undefined };
  }
  return { page: "agent" };
}

async function backendReachableNow(timeoutMs = 3500) {
  try {
    const res = await fetch("/api/health", { cache: "no-store", signal: requestTimeoutSignal(timeoutMs) });
    const data = await res.json().catch(() => ({}));
    return res.ok && data?.ok !== false;
  } catch {
    return false;
  }
}

function useBackendStatus(intervalMs = 6000): BackendStatus {
  const [refreshKey, setRefreshKey] = useState(0);
  const [state, setState] = useState<Omit<BackendStatus, "refresh">>({
    reachable: true,
    checking: true,
    message: "正在检查 Workbench 服务...",
  });

  useEffect(() => {
    let alive = true;
    const check = async () => {
      setState((current) => ({ ...current, checking: true }));
      try {
        const res = await fetch("/api/health", { cache: "no-store", signal: requestTimeoutSignal(5000) });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || data?.ok === false) throw new Error(data?.error || res.statusText);
        if (!alive) return;
        setState({
          reachable: true,
          checking: false,
          message: "",
          lastCheckedAt: new Date().toISOString(),
        });
      } catch (err) {
        if (!alive) return;
        setState({
          reachable: false,
          checking: false,
          message: toDisplayError(err instanceof Error ? err.message : String(err)),
          lastCheckedAt: new Date().toISOString(),
        });
      }
    };
    void check();
    const timer = window.setInterval(check, intervalMs);
    return () => {
      alive = false;
      window.clearInterval(timer);
    };
  }, [intervalMs, refreshKey]);

  return { ...state, refresh: () => setRefreshKey((value) => value + 1) };
}

function useApi<T>(path: string, deps: unknown[] = []) {
  const [state, setState] = useState<ApiState<T>>({ loading: true });
  useEffect(() => {
    let alive = true;
    setState((s) => ({ ...s, loading: true }));
    api<T>(path)
      .then((data) => alive && setState({ loading: false, data }))
      .catch((err) => alive && setState((current) => ({ ...current, loading: false, error: err.message })));
    return () => { alive = false; };
  }, deps);
  return state;
}

function useLiveEvents(enabled: boolean) {
  const [snapshot, setSnapshot] = useState<any>(null);
  const [connected, setConnected] = useState(false);
  useEffect(() => {
    if (!enabled) return;
    const source = new EventSource("/api/events");
    source.addEventListener("open", () => setConnected(true));
    source.addEventListener("error", () => setConnected(false));
    source.addEventListener("snapshot", (event) => {
      try {
        setSnapshot(JSON.parse((event as MessageEvent).data));
      } catch {
        setSnapshot(null);
      }
    });
    return () => source.close();
  }, [enabled]);
  return { snapshot, connected };
}

function useAgentWorkbenchStream(enabled: boolean) {
  const [snapshot, setSnapshot] = useState<any>(null);
  const [connected, setConnected] = useState(false);
  useEffect(() => {
    if (!enabled) return;
    const source = new EventSource("/api/agent-workbench/events");
    source.addEventListener("open", () => setConnected(true));
    source.addEventListener("error", () => setConnected(false));
    source.addEventListener("snapshot", (event) => {
      try {
        setSnapshot(JSON.parse((event as MessageEvent).data));
      } catch {
        setSnapshot(null);
      }
    });
    return () => source.close();
  }, [enabled]);
  return { snapshot, connected };
}

function inferRuntimeFromLocation(): RuntimeInfo {
  if (typeof window === "undefined") return { environment: "unknown", label: "UNKNOWN", source: "browser" };
  const port = Number(window.location.port || 0);
  if (port === 38889) return { environment: "dev", label: "DEV 测试环境", port, source: "browser" };
  if (port === 38890) return { environment: "staging", label: "STAGING 验收环境", port, source: "browser" };
  if (port === 38888) return { environment: "prod", label: "PROD 生产环境", port, source: "browser" };
  return { environment: "unknown", label: "UNKNOWN 环境", port: port || undefined, source: "browser" };
}

function runtimeLabel(environment: RuntimeEnvironment) {
  if (environment === "dev") return "DEV 测试环境";
  if (environment === "staging") return "STAGING 验收环境";
  if (environment === "prod") return "PROD 生产环境";
  if (environment === "preview") return "PREVIEW 预览环境";
  return "UNKNOWN 环境";
}

function useRuntimeEnvironment(): RuntimeInfo {
  const [runtime, setRuntime] = useState<RuntimeInfo>(() => inferRuntimeFromLocation());

  useEffect(() => {
    let alive = true;
    const copilot = typeof window !== "undefined" ? (window as any).njxCopilot : undefined;
    if (!copilot?.app?.getInfo && !copilot?.server?.getStatus) return;
    (async () => {
      try {
        const [infoResult, statusResult] = await Promise.allSettled([
          copilot.app?.getInfo?.(),
          copilot.server?.getStatus?.(),
        ]);
        if (!alive) return;
        const info = infoResult.status === "fulfilled" ? infoResult.value : {};
        const status = statusResult.status === "fulfilled" ? statusResult.value : {};
        const environment = String(info?.environment || status?.env || inferRuntimeFromLocation().environment || "unknown");
        const port = Number(status?.port || inferRuntimeFromLocation().port || 0) || undefined;
        setRuntime({
          environment,
          label: runtimeLabel(environment),
          port,
          appName: info?.appName || info?.productName,
          source: "desktop",
        });
      } catch {
        if (alive) setRuntime(inferRuntimeFromLocation());
      }
    })();
    return () => {
      alive = false;
    };
  }, []);

  return runtime;
}

function RuntimeBadge({ runtime, compact = false }: { runtime: RuntimeInfo; compact?: boolean }) {
  const tone = runtime.environment === "prod" ? "prod" : runtime.environment === "unknown" ? "unknown" : "nonprod";
  const port = runtime.port ? ` · ${runtime.port}` : "";
  return (
    <span className={`runtime-badge runtime-badge-${tone}${compact ? " runtime-badge-compact" : ""}`}>
      {runtime.label}{port}
    </span>
  );
}

function RuntimeBanner({ runtime }: { runtime: RuntimeInfo }) {
  return (
    <div className={`runtime-banner runtime-banner-${runtime.environment === "prod" ? "prod" : runtime.environment === "unknown" ? "unknown" : "nonprod"}`}>
      <strong>{runtime.label}</strong>
      {runtime.port ? <span>端口 {runtime.port}</span> : null}
      {runtime.appName ? <span>{runtime.appName}</span> : null}
    </div>
  );
}

function initialPageFromPath(): Page {
  return normalizeAppRouteFromPath().page;
}

function pagePath(page: Page, assistantDate?: string) {
  if (page === "agent") return "/agent";
  if (page === "tasks") return "/tasks";
  if (page === "assistant") return `/assistant${assistantDate ? `/${assistantDate}` : ""}`;
  return `/${page}`;
}

const pageMeta: Record<Page, { label: string; english: string; icon: string }> = {
  chat: { label: "对话", english: "Chat", icon: "C" },
  agent: { label: "智能体", english: "Agent", icon: "A" },
  overview: { label: "系统总览", english: "Overview", icon: "D" },
  tasks: { label: "指挥中心", english: "Command Center", icon: "⌘" },
  delivery: { label: "开发台", english: "Dev Console", icon: "V" },
  knowledge: { label: "知识库", english: "Knowledge", icon: "K" },
  graph: { label: "知识图谱", english: "Graph", icon: "G" },
  research: { label: "深度研究", english: "Research", icon: "R" },
  assistant: { label: "智能助理", english: "Assistant", icon: "H" },
  opc: { label: "OPC 运营", english: "Business", icon: "O" },
  projects: { label: "项目管理", english: "Projects", icon: "P" },
  mobile: { label: "手机配对", english: "Mobile", icon: "M" },
  system: { label: "系统设置", english: "System", icon: "S" },
};

const primaryNavPages: Page[] = ["chat", "agent", "overview", "tasks", "delivery", "knowledge", "research", "graph", "assistant", "opc", "projects", "system"];

export default function App() {
  const runtime = useRuntimeEnvironment();
  const [page, setPage] = useState<Page>(() => initialPageFromPath());
  const [assistantDate, setAssistantDate] = useState<string | undefined>(() => {
    const route = normalizeAppRouteFromPath();
    return route.page === "assistant" ? normalizeAssistantRouteDate(route.assistantDate) : undefined;
  });
  const [auth, setAuth] = useState<ApiState<{ ok: boolean; user?: unknown; error?: string }>>({ loading: true });
  const [refresh, setRefresh] = useState(0);
  const [chatNewSignal, setChatNewSignal] = useState(0);
  const [newConversationOpen, setNewConversationOpen] = useState(false);
  const live = useLiveEvents(Boolean(auth.data?.ok));
  // iter12: side-preview panel needs raw HTML keyed by basename(path). Fetched
  // here at the App level so both the GraphPage (uses KG3D) and any future
  // preview surfaces can share the same cache. The endpoint is cheap (~150KB
  // for 500 previews) and is re-keyed on the live snapshot version.
  const notePreviews = useApi<any>(`/api/knowledge/note-previews?limit=500`, [live.snapshot?.knowledge?.version || ""]);

  useEffect(() => {
    api<{ ok: boolean; user?: unknown }>("/api/auth/me")
      .then((data) => setAuth({ loading: false, data }))
      .catch((err) => setAuth({ loading: false, error: err.message }));
  }, [refresh]);

  useEffect(() => {
    const handlePopState = () => {
      const nextRoute = normalizeAppRouteFromPath();
      setPage(nextRoute.page);
      setAssistantDate(nextRoute.page === "assistant" ? normalizeAssistantRouteDate(nextRoute.assistantDate) : undefined);
    };
    window.addEventListener("popstate", handlePopState);
    return () => window.removeEventListener("popstate", handlePopState);
  }, []);

  useEffect(() => {
    const target = page === "assistant" ? pagePath(page, normalizeAssistantRouteDate(assistantDate)) : pagePath(page);
    if (window.location.pathname !== target) {
      window.history.replaceState({ page, assistantDate }, "", target);
    }
  }, [page, assistantDate]);

  if (auth.loading) return <Shell title="OpenClaw Workbench"><RuntimeBanner runtime={runtime} /><div className="loading">Loading</div></Shell>;
  if (auth.error) return <AuthScreen mode={auth.error === "setup_required" ? "setup" : "login"} onDone={() => setRefresh((v) => v + 1)} />;

  const pages: Array<{ id: Page; label: string; english: string; icon: string }> = primaryNavPages.map((id) => ({ id, ...pageMeta[id] }));
  const pageLabel = pageMeta[page]?.label || "系统设置";
  function openNewChat() {
    setNewConversationOpen(true);
  }
  function startBlankChat() {
    setNewConversationOpen(false);
    navigatePage("chat");
    setChatNewSignal((value) => value + 1);
  }
  async function startDevelopmentGoal(input: { projectId: string; projectName?: string; objective: string; successCriteria?: string }) {
    const objective = input.objective.trim();
    if (!objective) throw new Error("请输入任务目标。");
    let projectId = input.projectId;
    if (!projectId) {
      const data = await api<{ project: DevelopmentProjectSummary }>("/api/development/projects", {
        method: "POST",
        body: JSON.stringify({
          name: input.projectName?.trim() || objective.slice(0, 30) || "新开发项目",
          objective,
        }),
      });
      projectId = data.project.id;
    }
    await api(`/api/development/projects/${encodeURIComponent(projectId)}/goals`, {
      method: "POST",
      body: JSON.stringify({
        title: objective.slice(0, 42),
        objective,
        successCriteria: input.successCriteria || "可在真实 Electron app 中验收；有证据包、测试结果和下一步。",
        nextAction: "进入开发台，生成基线并运行 Goal OS preflight。",
      }),
    });
    setNewConversationOpen(false);
    navigatePage("delivery");
  }
  function navigatePage(nextPage: Page) {
    const nextDate = nextPage === "assistant" ? normalizeAssistantRouteDate(assistantDate) : undefined;
    if (nextPage === "assistant") setAssistantDate(nextDate);
    setPage(nextPage);
    const target = pagePath(nextPage, nextDate);
    if (window.location.pathname !== target) {
      window.history.pushState({ page: nextPage, assistantDate: nextDate }, "", target);
    }
  }

  const currentPageView = (
    <>
      {page === "chat" && <Chat newSessionSignal={chatNewSignal} onNavigate={navigatePage} />}
      {(page === "agent" || page === "tasks") && <AgentWorkbench onNavigate={navigatePage} />}
      {page === "delivery" && <DeliveryCore live={live} />}
      {page === "overview" && <Overview live={live} onNavigate={navigatePage} />}
      {page === "knowledge" && <Knowledge onNavigate={navigatePage} liveKnowledgeVersion={String(live.snapshot?.knowledge?.version || "")} />}
      {page === "graph" && <GraphPage onNavigate={navigatePage} nodePreviews={notePreviews.data?.previews} />}
      {page === "research" && <Research />}
      {page === "assistant" && <Assistant initialDate={assistantDate} onDateChange={setAssistantDate} />}
      {page === "opc" && <OpcManagement />}
      {page === "projects" && <Projects />}
      {page === "mobile" && <MobilePairingPage />}
      {page === "system" && <System live={live} onNavigate={navigatePage} />}
      {!(page === "agent" || page === "tasks" || page === "delivery") && <StatusBar live={live} />}
    </>
  );
  const framedPageView = page === "delivery"
    ? currentPageView
    : <WorkbenchPageShell page={page} live={live} onNavigate={navigatePage}>{currentPageView}</WorkbenchPageShell>;

  return (
    <div className="app app-runtime-bannered">
      <RuntimeBanner runtime={runtime} />
      <header className="sidebar app-topnav">
        <div className="brand">
          <div className="brand-mark"><img src="/brand-mark.svg" alt="OpenClaw" /></div>
          <div>
            <strong>OpenClaw</strong>
            <span>Workbench</span>
          </div>
          <RuntimeBadge runtime={runtime} compact />
        </div>
        <nav>
          {pages.map(({ id, label, english, icon }) => id === "chat" ? (
            <div className={page === id ? "nav-chat-row active" : "nav-chat-row"} key={id}>
              <button className="nav-main" onClick={() => navigatePage(id)} aria-label="对话">
                <span className="nav-icon" aria-hidden="true">{icon}</span>
                <span className="nav-label" title={english}><strong>{label}</strong></span>
              </button>
              <button className="nav-plus" onClick={openNewChat} aria-label="新建对话">+</button>
            </div>
          ) : (
            <button key={id} className={page === id ? "active" : ""} onClick={() => navigatePage(id)} aria-label={label}>
              <span className="nav-icon" aria-hidden="true">{icon}</span>
              <span className="nav-label" title={english}><strong>{label}</strong></span>
            </button>
          ))}
        </nav>
        <button className="ghost" onClick={() => api("/api/auth/logout", { method: "POST" }).then(() => setRefresh((v) => v + 1))}>退出登录</button>
      </header>
      <main className="main">
        {page !== "delivery" && <TopBar currentPage={page} currentLabel={pageLabel} live={live} onNavigate={navigatePage} />}
        {framedPageView}
      </main>
      {newConversationOpen ? (
        <NewConversationDialog
          onClose={() => setNewConversationOpen(false)}
          onStartChat={startBlankChat}
          onStartGoal={startDevelopmentGoal}
        />
      ) : null}
    </div>
  );
}

function MobilePairingPage({ embedded = false }: { embedded?: boolean } = {}) {
  const [refreshKey, setRefreshKey] = useState(0);
  const [deviceHint, setDeviceHint] = useState("iPhone Web App");
  const [pairing, setPairing] = useState<MobilePairing | null>(null);
  const [pairingError, setPairingError] = useState("");
  const [busy, setBusy] = useState(false);
  const [now, setNow] = useState(() => Date.now());
  const [qrDataUrl, setQrDataUrl] = useState("");
  const bootstrap = useApi<{ ok: true; mobile: MobileContract; service: { updatedAt: string } }>("/api/mobile/bootstrap", [refreshKey]);
  const devices = useApi<{ ok: true; devices: MobileDevice[] }>("/api/mobile/devices", [refreshKey]);
  const mobile = bootstrap.data?.mobile;
  const primaryServerUrl = mobile?.publicUrl || mobile?.lanUrls?.[0] || mobile?.localUrl || "";
  const pairingUrl = pairing ? `openclaw://pair?server=${encodeURIComponent(primaryServerUrl)}&code=${encodeURIComponent(pairing.code)}` : "";
  const pwaOrigin = pwaOriginFromServerUrl(primaryServerUrl);
  const pwaPairingUrl = pairing && pwaOrigin ? `${pwaOrigin}/web?server=${encodeURIComponent(pwaOrigin)}&code=${encodeURIComponent(pairing.code)}` : "";
  const qrTargetUrl = pwaPairingUrl || pairingUrl;
  const expiresAtMs = pairing ? Date.parse(pairing.expiresAt) : 0;
  const remainingSeconds = pairing ? Math.max(0, Math.ceil((expiresAtMs - now) / 1000)) : 0;
  const activeDevices = devices.data?.devices.filter((device) => device.status === "active").length || 0;

  useEffect(() => {
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    let active = true;
    if (!qrTargetUrl) {
      setQrDataUrl("");
      return () => { active = false; };
    }
    QRCode.toDataURL(qrTargetUrl, { margin: 1, width: 192, errorCorrectionLevel: "M" })
      .then((url) => active && setQrDataUrl(url))
      .catch((err) => active && setPairingError(err instanceof Error ? err.message : String(err)));
    return () => { active = false; };
  }, [qrTargetUrl]);

  async function startPairing() {
    setBusy(true);
    setPairingError("");
    try {
      const data = await api<{ ok: true; pairing: MobilePairing }>("/api/mobile/pairing/start", {
        method: "POST",
        body: JSON.stringify({ deviceHint: deviceHint.trim() || "iPhone Web App" }),
      });
      setPairing(data.pairing);
      setRefreshKey((value) => value + 1);
    } catch (err) {
      setPairingError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  }

  async function revokeDevice(id: string) {
    setBusy(true);
    setPairingError("");
    try {
      await api(`/api/mobile/devices/${encodeURIComponent(id)}/revoke`, { method: "POST", body: JSON.stringify({}) });
      setRefreshKey((value) => value + 1);
    } catch (err) {
      setPairingError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  }

  async function copy(text: string) {
    await navigator.clipboard?.writeText(text);
  }

  return (
    <section className={embedded ? "system-embedded-section mobile-pairing-page embedded" : "page mobile-pairing-page"}>
      <header>
        <div>
          <h1>移动设备配对</h1>
          <p>生成一次性配对码，把 iPhone Web App、TestFlight 或 Android APK 连接到这台 Mac Workbench；Mac 仍是唯一数据真相源。</p>
        </div>
        <div className="button-row">
          <button onClick={() => setRefreshKey((value) => value + 1)}>刷新状态</button>
          <button className="primary" onClick={startPairing} disabled={busy || !primaryServerUrl}>{busy ? "生成中" : "生成配对码"}</button>
        </div>
      </header>

      {pairingError && <div className="notice error"><span>{pairingError}</span></div>}
      {!primaryServerUrl && <div className="notice warning">未找到可给手机使用的 Workbench 地址。请确认服务监听端口，或配置 Cloudflare Tunnel 后设置 `OPENCLAW_MOBILE_PUBLIC_URL`。</div>}

      <div className="grid three mobile-status-grid">
        <div className="metric">
          <span>移动包名</span>
          <strong>{mobile?.packageName || "com.openclaw.mobile"}</strong>
        </div>
        <div className="metric">
          <span>更新通道</span>
          <strong>{mobile?.updateChannel || "preview"}</strong>
        </div>
        <div className="metric">
          <span>活跃设备</span>
          <strong>{activeDevices}</strong>
        </div>
      </div>

      <div className="grid two">
        <section className="panel mobile-pairing-card">
          <div className="panel-head">
            <div>
              <h2>一次性配对</h2>
              <small>5 分钟有效，单 code 单次使用</small>
            </div>
            <span className={remainingSeconds > 0 ? "status-chip status-pending" : "status-chip status-blocked"}>{remainingSeconds > 0 ? `${remainingSeconds}s` : "未生成"}</span>
          </div>
          <label className="field-label">设备说明</label>
          <input value={deviceHint} onChange={(event) => setDeviceHint(event.target.value)} placeholder="iPhone Web App / TestFlight / Android 真机" />
          <div className="pairing-code-box" aria-live="polite">{pairing?.code || "------"}</div>
          <div className="button-row">
            <button className="primary" onClick={startPairing} disabled={busy || !primaryServerUrl}>重新生成</button>
            <button onClick={() => pairing?.code && copy(pairing.code)} disabled={!pairing?.code}>复制配对码</button>
            <button onClick={() => pwaPairingUrl && copy(pwaPairingUrl)} disabled={!pwaPairingUrl}>复制 iPhone 链接</button>
            <button onClick={() => pairingUrl && copy(pairingUrl)} disabled={!pairingUrl}>复制原生深链</button>
          </div>
          <p className="muted">iPhone 推荐扫 Web App 配对二维码，会自动填入 Workbench 地址和 6 位码；TestFlight/Android 原生包也可手动输入。</p>
        </section>

        <section className="panel mobile-qr-card">
          <div className="panel-head">
            <div>
              <h2>扫码配对</h2>
              <small>{pwaPairingUrl ? "iPhone Web App 链接，包含同源地址和一次性 code" : "二维码只包含 Workbench 地址和一次性 code"}</small>
            </div>
          </div>
          {qrDataUrl ? <img className="mobile-qr" src={qrDataUrl} alt="OpenClaw 移动端配对二维码" /> : <div className="mobile-qr-placeholder">生成配对码后显示 QR</div>}
          <div className="mobile-url-list">
            <strong>推荐手机地址</strong>
            {pwaPairingUrl ? <code>{pwaPairingUrl}</code> : null}
            <code>{primaryServerUrl || "-"}</code>
          </div>
        </section>
      </div>

      <div className="grid two">
        <section className="panel">
          <div className="panel-head">
            <div>
              <h2>连接地址</h2>
              <small>同 Wi-Fi 优先 LAN；公网使用 Cloudflare HTTPS</small>
            </div>
          </div>
          <div className="mobile-url-list">
            <span>公网域名</span>
            <code>{mobile?.publicUrl || "未配置 OPENCLAW_MOBILE_PUBLIC_URL"}</code>
            <span>同 Wi-Fi 地址</span>
            {(mobile?.lanUrls?.length ? mobile.lanUrls : ["未发现 LAN IPv4 地址"]).map((url) => <code key={url}>{url}</code>)}
            <span>本机地址</span>
            <code>{mobile?.localUrl || "http://127.0.0.1:38888"}</code>
          </div>
        </section>

        <section className="panel">
          <div className="panel-head">
            <div>
              <h2>版本契约</h2>
              <small>后端兼容旧 App，JS/UI 用 preview OTA</small>
            </div>
          </div>
          <div className="mobile-contract-grid">
            <span>API</span><strong>{mobile?.apiVersion || "-"}</strong>
            <span>最低 App</span><strong>{mobile?.minSupportedAppVersion || "-"}</strong>
            <span>最新 App</span><strong>{mobile?.latestAppVersion || "-"} ({mobile?.latestAndroidVersionCode || 1})</strong>
            <span>同步模型</span><strong>{mobile?.syncModel || "mac_primary_online_write_offline_readonly"}</strong>
            <span>Build SHA</span><strong>{mobile?.buildSha || "-"}</strong>
          </div>
          {bootstrap.error && <p className="danger">版本契约读取失败：{bootstrap.error}</p>}
        </section>
      </div>

      <section className="panel">
        <div className="panel-head">
          <div>
            <h2>已配对设备</h2>
            <small>撤销后该设备 access/refresh token 会失效</small>
          </div>
          <button onClick={() => setRefreshKey((value) => value + 1)}>刷新设备</button>
        </div>
        {devices.error && <div className="notice error"><span>{devices.error}</span></div>}
        <div className="mobile-device-list">
          {(devices.data?.devices || []).map((device) => (
            <div className="mobile-device-row" key={device.id}>
              <div>
                <strong>{device.name || device.id}</strong>
                <span>{device.platform} · {device.appVersion || "unknown"} · last {device.lastSeenAt || "-"}</span>
              </div>
              <span className={`status-chip status-${device.status === "active" ? "approved" : "blocked"}`}>{device.status}</span>
              <button onClick={() => revokeDevice(device.id)} disabled={busy || device.status !== "active"}>撤销</button>
            </div>
          ))}
          {!devices.loading && !(devices.data?.devices || []).length && <p className="muted">暂无配对设备。生成 code 后在 iPhone Web App、TestFlight 或 Android App 中连接。</p>}
        </div>
      </section>
    </section>
  );
}

function pwaOriginFromServerUrl(serverUrl: string) {
  try {
    const parsed = new URL(serverUrl);
    const octets = parsed.hostname.split(".");
    if (octets.length === 4 && octets.every((part) => /^\d{1,3}$/.test(part) && Number(part) >= 0 && Number(part) <= 255)) {
      const hexHost = octets.map((part) => Number(part).toString(16).padStart(2, "0")).join("");
      return `http://${hexHost}.nip.io`;
    }
  } catch {
    return "";
  }
  return "";
}

function AuthScreen({ mode, onDone }: { mode: "setup" | "login"; onDone: () => void }) {
  const [password, setPassword] = useState("");
  const [remember, setRemember] = useState(true);
  const [error, setError] = useState("");
  const runtime = useRuntimeEnvironment();
  const copilot = typeof window !== "undefined" ? (window as any).njxCopilot : undefined;
  async function submit(e: FormEvent) {
    e.preventDefault();
    setError("");
    try {
      await api(mode === "setup" ? "/api/auth/setup" : "/api/auth/login", {
        method: "POST",
        body: JSON.stringify({ password })
      });
      // Desktop-only: persist the password encrypted in the OS keychain
      // (electron.safeStorage → macOS keychain) so we can auto-re-login
      // on next launch if the cookie / session drift apart. Web builds
      // simply no-op because `njxCopilot` is undefined.
      if (copilot?.auth?.rememberPassword && remember) {
        try {
          await copilot.auth.rememberPassword(password);
        } catch (persistErr) {
          console.warn("[auth] failed to persist password:", persistErr);
        }
      }
      if (copilot?.auth) {
        try {
          await copilot.auth.reconcileSession?.();
        } catch (reconcileErr) {
          console.warn("[auth] failed to reconcile session after login:", reconcileErr);
        }
        window.location.reload();
        return;
      }
      onDone();
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    }
  }
  return (
    <Shell title="OpenClaw Workbench">
      <RuntimeBanner runtime={runtime} />
      <form className="auth-card" onSubmit={submit}>
        <div className="auth-heading">
          <h1>{mode === "setup" ? "初始化工作台" : "登录工作台"}</h1>
          <RuntimeBadge runtime={runtime} />
        </div>
        <label>
          密码
          <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} minLength={6} autoFocus />
        </label>
        {copilot?.auth && (
          <label className="checkline">
            <input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} />
            记住密码（macOS 钥匙串加密；下次启动自动登录避免 cookie/session 失配）
          </label>
        )}
        {error && <p className="error">{error}</p>}
        <button type="submit">{mode === "setup" ? "创建账号" : "登录"}</button>
      </form>
    </Shell>
  );
}

function Shell({ title, children }: { title: string; children: React.ReactNode }) {
  return <div className="shell"><div className="shell-title">{title}</div>{children}</div>;
}

function TopBar({ currentPage, currentLabel, live, onNavigate }: { currentPage: Page; currentLabel: string; live: { snapshot: any; connected: boolean }; onNavigate: (page: Page) => void }) {
  const [query, setQuery] = useState("@njx-knowledge OpenClaw");
  const [results, setResults] = useState<any>(null);
  const [open, setOpen] = useState(false);
  const [inboxOpen, setInboxOpen] = useState(false);
  const [inboxTick, setInboxTick] = useState(0);
  const inbox = useApi<any>("/api/inbox", [inboxTick, live.snapshot?.ts]);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const inboxRows = inbox.data?.items || [];
  const unreadInbox = inboxRows.filter((row: any) => row.status === "unread");
  useEffect(() => {
    const handler = (event: globalThis.KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        inputRef.current?.focus();
      }
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "j") {
        event.preventDefault();
        onNavigate("assistant");
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [onNavigate]);
  async function submit(e?: FormEvent) {
    e?.preventDefault();
    if (!query.trim()) return;
    const data = await api<any>(`/api/search?q=${encodeURIComponent(query)}`);
    setResults(data.results);
    setOpen(true);
  }
  function quickKey(e: KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Escape") setOpen(false);
  }
  async function markInbox(id: string) {
    await api(`/api/inbox/${id}`, { method: "PATCH", body: JSON.stringify({ status: "read" }) });
    setInboxTick((value) => value + 1);
  }
  function queueAssistantSelection(kind: string, id: string) {
    window.localStorage.setItem(assistantSelectionStorageKey, JSON.stringify({ kind, id }));
    window.dispatchEvent(new Event("openclaw:assistant-selection"));
  }
  function openInboxItem(row: any) {
    const todoId = extractTodoIdFromInbox(row);
    if (todoId) queueAssistantSelection("todo", todoId);
    setInboxOpen(false);
    onNavigate("assistant");
  }
  function selectSearchResult(kind: string, row: any) {
    if (kind === "Todos" && row?.id) {
      queueAssistantSelection("todo", row.id);
      onNavigate("assistant");
    } else if (kind === "Tasks") {
      onNavigate("tasks");
    } else if (kind === "Projects") {
      onNavigate("projects");
    } else if (kind === "Knowledge") {
      onNavigate("knowledge");
    }
    setOpen(false);
  }
  return (
    <header className="topbar">
      <div className="topbar-page-title" aria-label="当前页面">
        <span>{pageMeta[currentPage]?.icon || "O"}</span>
        <strong>{currentLabel}</strong>
      </div>
      <form className="global-search" onSubmit={submit}>
        <input ref={inputRef} value={query} onKeyDown={quickKey} onChange={(e) => setQuery(e.target.value)} placeholder="搜索任务、知识、项目" />
        <button type="submit" aria-label="搜索">⌘K</button>
      </form>
      <div className="top-inbox">
        <button type="button" className={unreadInbox.length ? "top-inbox-button has-unread" : "top-inbox-button"} onClick={() => {
          setInboxTick((value) => value + 1);
          setInboxOpen((value) => !value);
        }}>
          Inbox {unreadInbox.length > 0 && <span className="badge">{unreadInbox.length}</span>}
        </button>
        {inboxOpen ? <div className="top-inbox-panel">
          <div className="panel-head"><strong>收件箱</strong><button className="secondary" type="button" onClick={() => onNavigate("agent")}>完整列表</button></div>
          {inbox.loading ? <p className="muted">加载中</p> : inboxRows.length === 0 ? <p className="muted">暂无提醒</p> : inboxRows.slice(0, 5).map((row: any) => <article className={row.status === "unread" ? "top-inbox-item unread" : "top-inbox-item"} key={row.id}>
            <button type="button" onClick={() => openInboxItem(row)}>
              <strong>{row.title}</strong>
              <span>{row.body}</span>
              <small>{row.agent_id || "main"} / {row.source} / {row.created_at}</small>
            </button>
            {row.status === "unread" ? <button className="secondary" type="button" onClick={() => markInbox(row.id)}>已读</button> : null}
          </article>)}
        </div> : null}
      </div>
      <div className="top-actions">
        <span className="breadcrumb">{live.connected ? "live" : "checking"}</span>
        <button onClick={() => onNavigate("system")}>{currentPage === "agent" || currentPage === "tasks" ? "系统状态" : live.connected ? "实时在线" : "实时检查中"}</button>
      </div>
      {open && <SearchPanel results={results} onClose={() => setOpen(false)} onSelect={selectSearchResult} />}
    </header>
  );
}

function SearchPanel({ results, onClose, onSelect }: { results: any; onClose: () => void; onSelect: (kind: string, row: any) => void }) {
  return (
    <div className="search-panel">
      <div className="panel-head">
        <strong>全局搜索</strong>
        <button onClick={onClose}>关闭</button>
      </div>
      <div className="grid four compact">
        <MiniGroup title="Tasks" rows={results?.tasks || []} onSelect={onSelect} />
        <MiniGroup title="Knowledge" rows={results?.knowledge || []} onSelect={onSelect} />
        <MiniGroup title="Todos" rows={results?.todos || []} onSelect={onSelect} />
        <MiniGroup title="Projects" rows={results?.projects || []} onSelect={onSelect} />
      </div>
    </div>
  );
}

function NewConversationDialog({
  onClose,
  onStartChat,
  onStartGoal,
}: {
  onClose: () => void;
  onStartChat: () => void;
  onStartGoal: (input: { projectId: string; projectName?: string; objective: string; successCriteria?: string }) => Promise<void>;
}) {
  const projectsState = useApi<{ ok: boolean; projects: DevelopmentProjectSummary[] }>("/api/development/projects", []);
  const projects = projectsState.data?.projects || [];
  const [projectId, setProjectId] = useState("");
  const [projectName, setProjectName] = useState("");
  const [objective, setObjective] = useState("");
  const [successCriteria, setSuccessCriteria] = useState("");
  const [busy, setBusy] = useState<"chat" | "goal" | "">("");
  const [error, setError] = useState("");
  const selectedProjectId = projectId || projects[0]?.id || "";

  async function submitGoal() {
    setError("");
    setBusy("goal");
    try {
      await onStartGoal({
        projectId: selectedProjectId,
        projectName,
        objective,
        successCriteria,
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy("");
    }
  }

  function submitChat() {
    setError("");
    setBusy("chat");
    onStartChat();
  }

  return (
    <div className="new-conversation-backdrop" role="presentation" onMouseDown={onClose}>
      <section className="new-conversation-dialog" role="dialog" aria-modal="true" aria-label="新对话" onMouseDown={(event) => event.stopPropagation()}>
        <header>
          <div>
            <span>NEW TASK</span>
            <h2>新对话</h2>
            <p>选择项目并开启一次任务；需要长期执行时直接创建开发目标。</p>
          </div>
          <button type="button" className="icon-button" onClick={onClose} aria-label="关闭">×</button>
        </header>
        <div className="new-conversation-body">
          <label>
            项目
            <select value={projectId} onChange={(event) => setProjectId(event.target.value)}>
              <option value="">{projects.length ? `默认：${projects[0]?.name}` : "新建开发项目"}</option>
              {projects.map((project) => <option value={project.id} key={project.id}>{project.name}</option>)}
            </select>
          </label>
          {!selectedProjectId ? (
            <label>
              新项目名称
              <input value={projectName} onChange={(event) => setProjectName(event.target.value)} placeholder="例如：OpenClaw Codex UI parity" />
            </label>
          ) : null}
          <label className="wide">
            任务目标
            <textarea value={objective} onChange={(event) => setObjective(event.target.value)} placeholder="你想让 OpenClaw / Codex 完成什么？" autoFocus />
          </label>
          <label className="wide">
            验收标准
            <textarea value={successCriteria} onChange={(event) => setSuccessCriteria(event.target.value)} placeholder="可选。写清楚真实 app、证据、测试和验收口径。" />
          </label>
          {projectsState.loading ? <p className="muted">正在加载项目...</p> : null}
          {projectsState.error ? <p className="form-error">{projectsState.error}</p> : null}
          {error ? <p className="form-error">{error}</p> : null}
        </div>
        <footer>
          <button type="button" className="secondary" onClick={onClose} disabled={Boolean(busy)}>取消</button>
          <button type="button" className="secondary" onClick={submitChat} disabled={Boolean(busy)}>{busy === "chat" ? "打开中" : "普通对话"}</button>
          <button type="button" onClick={submitGoal} disabled={Boolean(busy) || !objective.trim()}>{busy === "goal" ? "创建中" : "创建开发目标"}</button>
        </footer>
      </section>
    </div>
  );
}

type WorkbenchRailItem = {
  icon: string;
  label: string;
  meta?: string;
  tone?: "ok" | "warn" | "error";
  target?: Page;
};

type WorkbenchRailSection = {
  title: string;
  meta?: string;
  items: WorkbenchRailItem[];
};

type WorkbenchShellLayout = "standard" | "no-rail" | "no-inspector" | "focus";

function WorkbenchPageShell({ page, live, onNavigate, children }: { page: Page; live: { snapshot: any; connected: boolean }; onNavigate: (page: Page) => void; children: ReactNode }) {
  const model = getWorkbenchPageModel(page, live);
  const showRail = model.layout !== "no-rail" && model.layout !== "focus" && model.sections.length > 0;
  const showInspector = model.layout !== "no-inspector" && model.layout !== "no-rail" && model.layout !== "focus" && model.evidence.length > 0;
  return (
    <div className={`workbench-shell workbench-shell-${page} workbench-shell-${model.layout}`} aria-label={`${model.title} 工作区`}>
      {showRail ? (
        <aside className="workbench-context-rail" aria-label={`${model.title} 上下文`}>
          {model.sections.map((section) => (
            <section className="workbench-context-section" key={section.title}>
              <div className="workbench-context-title"><span>{section.title}</span>{section.meta ? <small>{section.meta}</small> : null}</div>
              {section.items.map((item) => (
                <button
                  key={`${section.title}-${item.icon}-${item.label}`}
                  type="button"
                  className={["workbench-context-item", item.tone || "", item.target === page ? "active" : ""].filter(Boolean).join(" ")}
                  onClick={() => item.target && onNavigate(item.target)}
                  disabled={!item.target}
                  title={item.meta || item.label}
                >
                  <span>{item.icon}</span>
                  <strong>{item.label}</strong>
                  {item.meta ? <small>{item.meta}</small> : null}
                </button>
              ))}
            </section>
          ))}
        </aside>
      ) : null}
      <section className="workbench-main-pane" aria-label={`${model.title} 主工作区`}>
        {children}
      </section>
      {showInspector ? (
        <aside className="workbench-inspector" aria-label={`${model.title} 检查器`}>
          <section className="workbench-inspector-card">
            <div className="workbench-inspector-title"><span>{model.title}</span><small>{model.status}</small></div>
            <p>{model.summary}</p>
            <div className="workbench-inspector-metrics">
              {model.metrics.map((metric) => (
                <div key={metric.label}><span>{metric.label}</span><strong>{metric.value}</strong></div>
              ))}
            </div>
          </section>
          <section className="workbench-inspector-card">
            <div className="workbench-inspector-title"><span>Evidence</span><small>{model.status}</small></div>
            {model.evidence.map((item) => (
              <button key={item.label} type="button" onClick={() => item.target && onNavigate(item.target)} disabled={!item.target}>
                <span>{item.icon}</span>
                <strong>{item.label}</strong>
                {item.meta ? <small>{item.meta}</small> : null}
              </button>
            ))}
          </section>
        </aside>
      ) : null}
    </div>
  );
}

