function extractTodoIdFromInbox(row: any) {
  const text = `${row?.body || ""}\n${row?.title || ""}`;
  const match = text.match(/待办\s*ID[：:]\s*([0-9a-f-]{16,})/i);
  return match?.[1] || "";
}

