function workbenchItemGoalId(item: WorkbenchTaskItem | null) {
  if (!item) return "";
  if (/^goal[-_:]/i.test(item.id)) return item.id;
  const linkedGoal = item.links?.find((link) => /goal/i.test(link.type) && /^goal[-_:]/i.test(link.target || ""));
  return linkedGoal?.target || "";
}

