function todoPlanType(row: any): TodoPlanType {
  if (row?.plan_type === "life" || row?.planType === "life") return "life";
  if (row?.plan_type === "work" || row?.planType === "work") return "work";
  const tags = parseTagChips(row?.tags);
  const haystack = [
    row?.title,
    row?.list_name,
    row?.source,
    row?.notes,
    ...tags,
  ].map((item) => String(item || "").toLowerCase()).join(" ");
  if (haystack.includes("五年规划") || haystack.includes("2026-2030") || /(^|\s)(个人|家庭|事业|社会)(\s|$)/.test(haystack)) return "life";
  if (haystack.includes("年度工作计划") || haystack.includes("2026年工作计划") || haystack.includes("2025年工作计划")) return "work";
  return "personal";
}
