function normalizePlanItemRow(item: any) {
  const rawFields = safeObject(item.raw_fields);
  const fieldOrder = parseStoredArray(item.field_order, Object.keys(rawFields));
  return {
    ...item,
    row_kind: "plan_item",
    raw_fields: rawFields,
    field_order: fieldOrder.length ? fieldOrder : Object.keys(rawFields),
    notes: item.notes || planItemNotes(rawFields),
    sync_status: item.sync_status || item.sync_status_override || "pending",
  };
}

function planItemNotes(rawFields: Record<string, unknown>) {
  return Object.entries(rawFields)
    .filter(([key, value]) => value && !["任务描述", "具体行动项（行）", "待办事项"].includes(key))
    .slice(0, 8)
    .map(([key, value]) => `${key}：${String(value).slice(0, 120)}`)
    .join("\n");
}

function safeObject(value: unknown): Record<string, unknown> {
  if (value && typeof value === "object" && !Array.isArray(value)) return value as Record<string, unknown>;
  if (typeof value !== "string") return {};
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
  } catch {
    return {};
  }
}
