function isDevelopmentRunInstructionText(input: string) {
  const text = String(input || "").trim();
  if (!text) return false;
  const hasQuestionIntent = /为什么|为啥|干嘛|有没有|如何|怎么|是什么|是否一定|替代方案|\?/.test(text);
  const strongRunIntent = /同意执行|继续执行|执行当前|开始执行|调用代理|调用.*agent|使用\s*open\s*claw\s*实现|用\s*open\s*claw\s*实现|实现\s*web[_ -]?search|修复\s*web[_ -]?search|推进当前|继续推进|落地当前/i.test(text);
  if (strongRunIntent) return true;
  if (hasQuestionIntent) return false;
  return /(执行|开始|继续|推进|处理|修复|实现|开发|落地)/i.test(text) && /(当前|子任务|web[_ -]?search|open\s*claw|代理|agent)/i.test(text);
}

function isExplicitAcceptanceEvidence(input: string) {
  const text = String(input || "").replace(/\s+/g, " ").trim();
  if (text.length < 12) return false;
  if (/请填写证据|待补充|占位|placeholder|todo|tbd/i.test(text)) return false;
  if (/^(同意|通过|确认|验收通过|人工确认|ok|yes|pass|approved)[。.!！\s]*$/i.test(text)) return false;
  return /(npm run|pnpm|yarn|playwright|截图|screenshot|\/Users\/|\/tmp\/|\.png|\.md|\.html|\.log|产物|证据|审核|验收|用户确认|app 验收|Electron|真实 app|build|check|test|codesign)/i.test(text);
}

function compactDevelopmentGoalTitle(goal?: Pick<DevelopmentGoal, "title" | "objective"> | null, maxLength = 68) {
  const raw = String(goal?.title || goal?.objective || "").replace(/\s+/g, " ").trim();
  if (!raw) return "";
  const firstSentence = raw.split(/(?<=[。！？!?])\s*/)[0]?.trim() || raw;
  const candidate = firstSentence.length >= 12 ? firstSentence : raw;
  return candidate.length > maxLength ? `${candidate.slice(0, maxLength - 1)}…` : candidate;
}

function developmentInitialSelection() {
  const params = new URLSearchParams(window.location.search);
  return {
    projectId: params.get("project") || params.get("projectId") || window.localStorage.getItem("development-active-project") || "",
    goalId: params.get("goal") || params.get("goalId") || window.localStorage.getItem("development-active-goal") || "",
  };
}

