  async function loadGoalContinuationContract(copyPrompt = false) {
    if (!activeGoal) {
      setGoalNotice({ tone: "warn", message: "当前项目还没有长期目标，请先创建目标。" });
      return;
    }
    if (copyPrompt) {
      await commitGoalContinuationContract("copy");
      return;
    }
    setGoalBusy(true);
    setGoalNotice(null);
    try {
      const data = await api<{ ok: boolean; continuationContract: DevelopmentGoalContinuationContract }>(`/api/development/goals/${encodeURIComponent(activeGoal.id)}/continuation-contract`);
      setGoalContinuationContract(data.continuationContract);
      if (copyPrompt) {
        try {
          await navigator.clipboard?.writeText(data.continuationContract.nextPrompt || data.continuationContract.markdown);
          setGoalNotice({ tone: "ok", message: `续跑契约已复制：${data.continuationContract.readinessLabel} · ${data.continuationContract.readinessScore}/100` });
        } catch {
          setGoalNotice({ tone: "ok", message: `续跑契约已生成：${data.continuationContract.readinessLabel} · ${data.continuationContract.readinessScore}/100` });
        }
      } else {
        setGoalNotice({
          tone: data.continuationContract.blockers.length || data.continuationContract.requiredEvidence.length ? "warn" : "ok",
          message: `续跑契约：${data.continuationContract.readinessLabel} · ${data.continuationContract.readinessScore}/100 · 已保存产物 ${data.continuationContract.artifact?.title || "Goal Continuation Contract"}`,
        });
      }
    } catch (err) {
      setGoalNotice({ tone: "error", message: err instanceof Error ? err.message : String(err) });
    } finally {
      setGoalBusy(false);
    }
  }

  async function commitGoalContinuationContract(action: "copy" | "stage" | "continue") {
    if (!activeGoal) {
      setGoalNotice({ tone: "warn", message: "当前项目还没有长期目标，请先创建目标。" });
      return;
    }
    const startedAt = new Date().toISOString();
    setGoalBusy(true);
    setGoalNotice(null);
    if (action === "continue") {
      setExecutionPulse({
        id: `goal-contract-pulse-${Date.now()}`,
        subtaskId: activeSubtask?.id || activeGoal.activeSubtaskId || "",
        subtaskTitle: activeSubtask?.title || activeGoal.title,
        status: "running",
        message: "已按续跑契约发起目标心跳，正在对齐上下文并等待事件回写。",
        startedAt,
        blockers: [],
      });
    }
    try {
      const data = await api<{ ok: boolean; continuationContract: DevelopmentGoalContinuationContract; detail?: DevelopmentDetail; goal?: DevelopmentGoal | null; run?: DevelopmentRun | null; feedback?: string | null }>(`/api/development/goals/${encodeURIComponent(activeGoal.id)}/continuation-contract`, {
        method: "POST",
        body: JSON.stringify({ action, activeAgentId: activeAgentId || "main" }),
      });
      setGoalContinuationContract(data.continuationContract);
      if (data.detail) {
        setLiveDetail(data.detail);
        setActiveWorkPacketId(data.goal?.activeWorkPacketId || data.detail.activeWorkPacket?.id || "");
        setActiveSubtaskId(data.goal?.activeSubtaskId || data.detail.baseline?.currentSubtask?.id || "");
      }
      if (data.goal) setActiveGoalId(data.goal.id);
      if (action === "copy") {
        try {
          await navigator.clipboard?.writeText(data.continuationContract.nextPrompt || data.continuationContract.markdown);
          setGoalNotice({ tone: "ok", message: `续跑契约已写入账本并复制：${data.continuationContract.readinessLabel} · ${data.continuationContract.readinessScore}/100` });
        } catch {
          setGoalNotice({ tone: "ok", message: `续跑契约已写入账本：${data.continuationContract.readinessLabel} · ${data.continuationContract.readinessScore}/100` });
        }
      } else if (action === "stage") {
        fillComposer(data.continuationContract.nextPrompt || data.continuationContract.nextCommand, "自动审查");
        setGoalNotice({ tone: data.continuationContract.blockers.length || data.continuationContract.requiredEvidence.length ? "warn" : "ok", message: `续跑契约已接入输入框：${data.continuationContract.readinessLabel} · ${data.continuationContract.readinessScore}/100` });
      } else {
        const completedAt = new Date().toISOString();
        const dispatched = data.run?.status === "running" || data.run?.status === "dispatched";
        const blocked = data.run?.status === "blocked" || data.feedback === "baseline_not_locked";
        setExecutionPulse((pulse) => pulse?.id.startsWith("goal-contract-pulse-") ? {
          ...pulse,
          status: dispatched ? "dispatched" : blocked ? "blocked" : data.run ? "completed" : "queued",
          completedAt,
          blockers: blocked ? [data.feedback === "baseline_not_locked" ? "基线尚未锁定，续跑契约已停在人工确认点。" : data.run?.summary || "按契约继续时遇到阻塞。"] : [],
          message: dispatched
            ? "已按续跑契约派发给 OpenClaw 代理后台运行，等待事件回写。"
            : blocked
              ? "续跑契约已写入账本，但当前处于人工确认或阻塞点。"
              : data.run?.summary || "续跑契约已写入账本，等待下一轮继续。",
        } : pulse);
        window.setTimeout(() => setExecutionPulse((pulse) => pulse?.id.startsWith("goal-contract-pulse-") ? null : pulse), dispatched ? 15000 : 7000);
        setGoalNotice({ tone: blocked ? "warn" : "ok", message: blocked ? "按契约继续已停止在人工门控。" : `已按续跑契约继续：${data.continuationContract.readinessLabel}` });
      }
      setTick((value) => value + 1);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      setGoalNotice({ tone: "error", message });
      setExecutionPulse((pulse) => pulse?.id.startsWith("goal-contract-pulse-") ? { ...pulse, status: "error", completedAt: new Date().toISOString(), blockers: [message], message } : pulse);
    } finally {
      setGoalBusy(false);
    }
  }

  function goalContinuationPrimaryLabel(contract: DevelopmentGoalContinuationContract) {
    if (/先锁定基线/.test(contract.readinessLabel)) return "锁定基线";
    if (/可继续执行/.test(contract.readinessLabel)) return "按契约继续";
    if (/可结束审计/.test(contract.readinessLabel)) return "完成审计";
    return "接入输入框";
  }

  function runGoalContinuationPrimaryAction(contract: DevelopmentGoalContinuationContract) {
    if (/先锁定基线/.test(contract.readinessLabel)) {
      void lockBaseline();
      return;
    }
    if (/可继续执行/.test(contract.readinessLabel)) {
      void commitGoalContinuationContract("continue");
      return;
    }
    if (/可结束审计/.test(contract.readinessLabel)) {
      void loadGoalCompletionAudit();
      return;
    }
    void commitGoalContinuationContract("stage");
  }

  function runGoalTimelineAction(actionKey: string) {
    if (actionKey === "continuation_contract") {
      void loadGoalContinuationContract();
      return;
    }
    if (actionKey === "evidence_pack") {
      void loadGoalEvidencePack();
      return;
    }
    if (actionKey === "completion_audit") {
      void loadGoalCompletionAudit();
      return;
    }
    if (actionKey === "recovery_packet") {
      void loadGoalRecoveryPacket();
      return;
    }
    if (actionKey === "learning_review") {
      void loadGoalLearningReview();
      return;
    }
    if (actionKey === "continue_goal") {
      void runGoalAction(activeGoal?.status === "paused" ? "resume" : "continue");
      return;
    }
    if (actionKey === "enable_autopilot") {
      void runGoalAction("enable_auto");
      return;
    }
    if (actionKey === "auto_check") {
      void runGoalAction("auto_check");
      return;
    }
    if (actionKey === "lock_baseline") {
      void lockBaseline();
      return;
    }
    setGoalNotice({ tone: "warn", message: `暂未绑定动作：${actionKey}` });
  }

  function runGoalRunwayAction(actionKey: string) {
    if (actionKey === "stage_contract") {
      void commitGoalContinuationContract("stage");
      return;
    }
    if (actionKey === "continue_contract") {
      void commitGoalContinuationContract("continue");
      return;
    }
    if (actionKey === "refresh_runway") {
      void loadGoalRunway();
      return;
    }
    runGoalTimelineAction(actionKey);
  }

  async function recordGoalOperatingAction(actionKey: string, note = "") {
    if (!activeGoal) return;
    try {
      const data = await api<{ ok: boolean; action: { key: string; label: string; detail: string; tone: string }; snapshot: DevelopmentGoalOperatingSnapshot }>(`/api/development/goals/${encodeURIComponent(activeGoal.id)}/operating-actions`, {
        method: "POST",
        body: JSON.stringify({ actionKey, note }),
      });
      setGoalOperatingSnapshot(data.snapshot);
    } catch (err) {
      setGoalNotice({
        tone: "warn",
        message: `目标动作审计写入失败，仍继续执行当前操作：${err instanceof Error ? err.message : String(err)}`,
      });
    }
  }

  async function runGoalSnapshotAction(actionKey: string) {
    await recordGoalOperatingAction(actionKey);
    if (actionKey === "dispatch_recovery") {
      void stageGoalDispatchRecovery();
      return;
    }
    if (actionKey === "resolve_blocker") {
      if (goalDispatchFailure) {
        void stageGoalDispatchRecovery();
        return;
      }
      void loadGoalRecoveryPacket();
      return;
    }
    if (actionKey === "create_artifact") {
      void loadGoalEvidencePack();
      return;
    }
    runGoalRunwayAction(actionKey);
  }

