  async function prepareGoalCodexRuntime() {
    if (!activeGoal) {
      setGoalNotice({ tone: "warn", message: "当前项目还没有长期目标，请先创建目标。" });
      return;
    }
    const goalId = activeGoal.id;
    setGoalBusy(true);
    setGoalNotice({ tone: "ok", message: "正在准备 Codex Goal 接力材料：续跑契约、证据包、恢复包和跑道。" });
    try {
      const [contractData, evidenceData] = await Promise.all([
        api<{ ok: boolean; continuationContract: DevelopmentGoalContinuationContract }>(`/api/development/goals/${encodeURIComponent(goalId)}/continuation-contract`),
        api<{ ok: boolean; evidencePack: DevelopmentGoalEvidencePack }>(`/api/development/goals/${encodeURIComponent(goalId)}/evidence-pack`),
      ]);
      setGoalContinuationContract(contractData.continuationContract);
      setGoalEvidencePack(evidenceData.evidencePack);
      const recoveryData = await api<{ ok: boolean; packet: DevelopmentGoalRecoveryPacket; detail: DevelopmentDetail }>(`/api/development/goals/${encodeURIComponent(goalId)}/recovery-packet`);
      setGoalRecoveryPacket(recoveryData.packet);
      setLiveDetail(recoveryData.detail);
      const runwayData = await api<{ ok: boolean; runway: DevelopmentGoalRunway; detail?: DevelopmentDetail; goal?: DevelopmentGoal | null }>(`/api/development/goals/${encodeURIComponent(goalId)}/runway`, {
        method: "POST",
      });
      setGoalRunway(runwayData.runway);
      if (runwayData.detail) setLiveDetail(runwayData.detail);
      if (runwayData.goal) setActiveGoalId(runwayData.goal.id);
      const timelineData = await api<{ ok: boolean; timeline: DevelopmentGoalTimeline }>(`/api/development/goals/${encodeURIComponent(goalId)}/timeline`);
      setGoalTimeline(timelineData.timeline);
      const missing = [
        ...contractData.continuationContract.blockers,
        ...contractData.continuationContract.requiredEvidence,
        ...evidenceData.evidencePack.blockers,
        ...evidenceData.evidencePack.missingEvidence,
      ].filter((item, index, list) => item && list.indexOf(item) === index);
      setGoalNotice({
        tone: missing.length ? "warn" : "ok",
        message: missing.length
          ? `接力材料已准备，但仍有 ${missing.length} 个停机点/证据缺口：${missing[0]}`
          : `接力材料已准备：证据 ${evidenceData.evidencePack.coverageScore}/100 · 恢复包 ${recoveryData.packet.events.length} events · 跑道 ${runwayData.runway.readinessScore}/100`,
      });
      setTick((value) => value + 1);
    } catch (err) {
      setGoalNotice({ tone: "error", message: err instanceof Error ? err.message : String(err) });
    } finally {
      setGoalBusy(false);
    }
  }

  async function stageGoalDispatchRecovery() {
    if (!activeGoal) {
      setGoalNotice({ tone: "warn", message: "当前项目还没有长期目标，请先创建目标。" });
      return;
    }
    setGoalBusy(true);
    setGoalNotice({ tone: "warn", message: "正在把派发恢复写入目标账本，并生成可接力恢复提示。" });
    try {
      const data = await api<{ ok: boolean; dispatchRecovery: DevelopmentGoalDispatchRecovery; goal?: DevelopmentGoal | null; detail?: DevelopmentDetail; timeline?: DevelopmentGoalTimeline | null }>(`/api/development/goals/${encodeURIComponent(activeGoal.id)}/dispatch-recovery`, {
        method: "POST",
        body: JSON.stringify({ reason: goalDispatchFailureReason }),
      });
      if (data.detail) setLiveDetail(data.detail);
      if (data.goal) setActiveGoalId(data.goal.id);
      if (data.timeline) setGoalTimeline(data.timeline);
      setGoalDispatchRecovery(data.dispatchRecovery);
      try {
        const snapshotData = await api<{ ok: boolean; snapshot: DevelopmentGoalOperatingSnapshot }>(`/api/development/goals/${encodeURIComponent(activeGoal.id)}/operating-snapshot`);
        setGoalOperatingSnapshot(snapshotData.snapshot);
      } catch {
        // The recovery artifact is already persisted; stale snapshot will refresh on the next poll.
      }
      fillComposer(data.dispatchRecovery.prompt || goalDispatchRecoveryPrompt, "自动审查");
      setGoalNotice({
        tone: "warn",
        message: `派发恢复已写入目标账本：${data.dispatchRecovery.reason} · ${data.dispatchRecovery.artifact?.title || "恢复提示已生成"}`,
      });
      setTick((value) => value + 1);
    } catch (err) {
      fillComposer(goalDispatchRecoveryPrompt, "自动审查");
      setGoalNotice({
        tone: "error",
        message: `派发恢复未能写入账本，已生成本地恢复提示：${err instanceof Error ? err.message : String(err)}`,
      });
    } finally {
      setGoalBusy(false);
    }
  }

  async function resolveGoalDispatchRecovery() {
    if (!activeGoal) {
      setGoalNotice({ tone: "warn", message: "当前项目还没有长期目标，请先创建目标。" });
      return;
    }
    setGoalBusy(true);
    setGoalNotice({ tone: "warn", message: "正在向 Gateway 验证派发状态并清理派发失败 blocker…" });
    try {
      const data = await api<{
        ok: boolean;
        resolved: boolean;
        health?: { status?: string; source?: string; error?: string };
        dispatchResolution?: {
          resolvedAt?: string;
          previousStatus?: string;
          nextStatus?: string;
          remainingBlockers?: string[];
          subtaskCleanup?: { subtaskId: string; previousBlockers: string[]; remainingBlockers: string[] } | null;
          idempotent?: boolean;
          nextAction?: string;
        };
        goal?: DevelopmentGoal | null;
        detail?: DevelopmentDetail;
        timeline?: DevelopmentGoalTimeline | null;
        snapshot?: DevelopmentGoalOperatingSnapshot;
      }>(`/api/development/goals/${encodeURIComponent(activeGoal.id)}/dispatch-recovery`, {
        method: "POST",
        body: JSON.stringify({ action: "resolve" }),
      });
      if (data.detail) setLiveDetail(data.detail);
      if (data.goal) setActiveGoalId(data.goal.id);
      if (data.timeline) setGoalTimeline(data.timeline);
      if (data.snapshot) setGoalOperatingSnapshot(data.snapshot);
      // 主动刷新 snapshot，确保阻塞死区 UI 立即清掉
      try {
        const snapshotData = await api<{ ok: boolean; snapshot: DevelopmentGoalOperatingSnapshot }>(`/api/development/goals/${encodeURIComponent(activeGoal.id)}/operating-snapshot`);
        setGoalOperatingSnapshot(snapshotData.snapshot);
      } catch {
        // snapshot may already be in data.snapshot
      }
      if (data.resolved) {
        const clean = data.dispatchResolution?.subtaskCleanup;
        const cleanHint = clean ? ` · 子任务 #${clean.subtaskId.slice(-6)} blockers 已清理` : "";
        const idempotentHint = data.dispatchResolution?.idempotent ? "（幂等：此前已恢复，本次再次确认）" : "";
        setGoalNotice({
          tone: "ok",
          message: `派发已恢复：${data.dispatchResolution?.nextStatus || data.goal?.status || "active"} · Gateway ${data.health?.status || "connected"}${cleanHint}${idempotentHint}`,
        });
      } else {
        // health 未通过，resolved = false：暴露原因，不允许"Failed to fetch"裸错
        const reason = data.health?.error || data.health?.status || "Gateway 健康检查未通过";
        setGoalNotice({
          tone: "warn",
          message: `派发恢复验证未通过：${reason}。请先恢复 Gateway / 代理接手，再重试。`,
        });
      }
      setTick((value) => value + 1);
    } catch (err) {
      setGoalNotice({
        tone: "error",
        message: `验证并恢复派发失败：${err instanceof Error ? err.message : String(err)}`,
      });
    } finally {
      setGoalBusy(false);
    }
  }

