  function focusComposer() {
    window.requestAnimationFrame(() => composerInputRef.current?.focus());
  }

  function fillComposer(nextText: string, nextReviewMode = "自动审查") {
    setReviewMode(nextReviewMode);
    setComposerText(nextText);
    setComposerNotice(null);
    setComposerManualMode(true);
    focusComposer();
  }

  function openTaskLauncher(seed = "") {
    setTaskLauncherDraft((value) => ({
      ...value,
      projectId: value.projectId || effectiveProjectId,
      prompt: seed || value.prompt,
      branch: value.branch || "main",
      mode: value.mode || "本地模式",
      context: value.context || "repo",
    }));
    setTaskLauncherNotice(null);
    setTaskLauncherOpen(true);
    window.setTimeout(() => {
      const input = document.querySelector(".delivery-task-launcher textarea") as HTMLTextAreaElement | null;
      input?.focus();
    }, 80);
  }

  async function startTaskFromLauncher(event?: FormEvent<HTMLFormElement>) {
    event?.preventDefault();
    const naturalLanguage = taskLauncherDraft.prompt.trim();
    const targetProjectId = taskLauncherDraft.projectId || effectiveProjectId;
    if (!targetProjectId) {
      setTaskLauncherNotice({ tone: "warn", message: "请先选择项目。" });
      return;
    }
    if (!naturalLanguage) {
      setTaskLauncherNotice({ tone: "warn", message: "请输入要开启的任务目标。" });
      return;
    }
    setTaskLauncherBusy(true);
    setTaskLauncherNotice(null);
    try {
      const data = await api<{
        ok: boolean;
        goal?: DevelopmentGoal | null;
        detail?: DevelopmentDetail | null;
        parse?: { fallback?: boolean; parsed?: { subtasks?: Array<{ title?: string }> }; durationMs?: number } | null;
      }>("/api/development/goals/from-natural-language", {
        method: "POST",
        body: JSON.stringify({
          naturalLanguage,
          projectId: targetProjectId,
          agentId: activeAgentId || "main",
          sessionKey: `dev-console:${targetProjectId}:task-launcher`,
        }),
      });
      if (!data.goal) throw new Error("任务启动失败：后端没有返回 goal。");
      const detail = data.detail || null;
      const goal = data.goal;
      const createdAt = new Date().toISOString();
      if (targetProjectId !== activeProjectId) preserveProjectSelectionRef.current = true;
      setActiveProjectId(targetProjectId);
      setActiveGoalId(goal.id);
      setActiveWorkPacketId(goal.activeWorkPacketId || detail?.activeWorkPacket?.id || "");
      setActiveSubtaskId(goal.activeSubtaskId || detail?.baseline?.currentSubtask?.id || "");
      setActiveTaskId("");
      setActiveEvidence(null);
      setDocDrawerOpen(false);
      setLiveDetail(detail);
      setRecentLauncherPrompt(naturalLanguage);
      setOptimisticEvents((items) => [
        ...items,
        {
          id: `launcher-owner-${Date.now()}`,
          type: "message",
          actor: "owner",
          severity: "info",
          message: naturalLanguage,
          createdAt,
          payload: { source: "codex_task_launcher", mode: taskLauncherDraft.mode, branch: taskLauncherDraft.branch, context: taskLauncherDraft.context },
        },
        {
          id: `launcher-openclaw-${Date.now() + 1}`,
          type: data.parse?.fallback ? "blocker" : "review",
          actor: activeAgentId || "main",
          severity: data.parse?.fallback ? "warn" : "info",
          message: data.parse?.fallback
            ? `已用 fallback 开启任务：${goal.title}。下一步需要人工确认目标拆解和验收标准。`
            : `已开启任务：${goal.title}。${data.parse?.parsed?.subtasks?.length ? `拆解 ${data.parse.parsed.subtasks.length} 个子任务。` : "等待生成任务基线。"}`,
          createdAt,
          payload: { source: "codex_task_launcher", goalId: goal.id },
        },
      ].slice(-36));
      setTaskLauncherDraft((value) => ({ ...value, prompt: "" }));
      setTaskLauncherOpen(false);
      setComposerNotice({
        tone: data.parse?.fallback ? "warn" : "ok",
        message: data.parse?.fallback ? `任务已开启但使用 fallback：${goal.title}` : `任务已开启：${goal.title}`,
      });
      setTick((value) => value + 1);
      window.setTimeout(() => composerInputRef.current?.focus(), 120);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      setTaskLauncherNotice({ tone: "error", message });
      setGoalDraft((value) => ({
        ...value,
        title: value.title || naturalLanguage.slice(0, 60),
        objective: value.objective || naturalLanguage,
      }));
    } finally {
      setTaskLauncherBusy(false);
    }
  }

