function AgentComputerEvidenceSurface({ agent, item, telemetry, logs, artifacts, recommendedAction, primaryLabel, onPrimaryAction, onPanel, onAutonomyAction }: {
  agent: AgentWorkbenchAgent;
  item: WorkbenchTaskItem | null;
  telemetry: AgentOpsTelemetry;
  logs: Array<{ title: string; meta: string; message: string }>;
  artifacts: Array<{ label: string; path: string; type: string; exists: boolean }>;
  recommendedAction: { tone: string; title: string; detail: string };
  primaryLabel: string;
  onPrimaryAction: () => void;
  onPanel: (panel: AgentEvidencePanelKey) => void;
  onAutonomyAction: (item: WorkbenchTaskItem | null, action: string, message?: string) => void;
}) {
  const trust = automationTrust(agent, item);
  const motion = trust.level === "high" ? "working" : trust.level === "watch" ? "watch" : trust.level === "human" ? "human" : trust.level === "recover" ? "recover" : "idle";
  const outputLines = agentComputerOutputLines(agent, item, logs, artifacts, trust);
  return <article className={`agent-computer-evidence trust-${trust.level} motion-${motion}`} aria-label={`${openClawAgentLabel(agent.id)} 工位电脑`}>
    <div className="agent-computer-evidence-head">
      <span className={`agent-computer-avatar agent-${agent.id}`}>{agentBadgeLetter(agent.id)}</span>
      <div>
        <span>Workstation / 可操作电脑</span>
        <strong>{openClawAgentLabel(agent.id)} · {agentMotionLabel(motion)}</strong>
        <small>{trust.evidence}</small>
      </div>
    </div>
    <div className="agent-computer-screen-shell">
      <div className="agent-computer-screen-top">
        <span>{agentDeskScreenText({ agent, current: item, trust, visualStatus: "", progress: Number(item?.progressPercent || agent.progressPercent || 0), destination: agentOfficeDestination(trust), destinationLabel: agentOfficeDestinationLabel(agentOfficeDestination(trust)) })}</span>
        <strong>{trust.score === null ? trust.label : `${trust.label} · ${trust.score}`}</strong>
      </div>
      <div className="agent-computer-screen-lines">
        {outputLines.map((line, index) => <p key={index}><span>{line.kind}</span><strong>{line.text}</strong></p>)}
      </div>
      {item ? <TaskProgressBar
        percent={Number(item.progressPercent || agent.progressPercent || 0)}
        label={agentTrustProgressLabel(trust, item, item.status || "", Number(item.progressPercent || agent.progressPercent || 0))}
        tone={item.status}
        trustLevel={trust.level}
      /> : null}
    </div>
    <div className="agent-computer-evidence-metrics">
      <div><span>Token</span><strong>{telemetry.tokenEstimate}</strong><small>{telemetry.tokenNote}</small></div>
      <div><span>文字</span><strong>{telemetry.textEdits}</strong><small>{telemetry.rateWindowName}</small></div>
      <div><span>产物</span><strong>{artifacts.length}</strong><small>PLAN / RESULT / files</small></div>
      <div><span>最新</span><strong>{logs[0]?.title || "none"}</strong><small>{logs[0]?.meta || "等待事件"}</small></div>
    </div>
    <div className="agent-computer-command">
      <div>
        <strong>{recommendedAction.title}</strong>
        <span>{recommendedAction.detail}</span>
      </div>
      <div className="agent-computer-command-actions">
        <button type="button" className="primary" onClick={onPrimaryAction}>{primaryLabel}</button>
        <button type="button" onClick={() => onPanel("logs")}>日志</button>
        <button type="button" onClick={() => onPanel("artifacts")}>产出物</button>
        {trust.level === "recover" ? <button type="button" onClick={() => onAutonomyAction(item, "recover_prompt")}>恢复提示</button> : null}
      </div>
    </div>
  </article>;
}

function agentComputerOutputLines(
  agent: AgentWorkbenchAgent,
  item: WorkbenchTaskItem | null,
  logs: Array<{ title: string; meta: string; message: string }>,
  artifacts: Array<{ label: string; path: string; type: string; exists: boolean }>,
  trust: AgentAutomationTrust,
) {
  const currentTitle = compactWorkbenchTitle(item?.title, `${openClawAgentLabel(agent.id)} 当前无自动化任务`);
  const summary = compactWorkbenchTitle(item?.currentSummary || item?.nextStep || trust.evidence, trust.evidence);
  const latest = compactWorkbenchTitle(logs[0]?.message, trust.level === "idle" ? "等待新的任务输入" : "等待下一条执行事件");
  const artifactSummary = artifacts.length
    ? artifacts.slice(0, 3).map((artifact) => artifact.label || artifact.path.split("/").pop()).join(" / ")
    : "暂无可预览产物";
  if (trust.level === "recover") return [
    { kind: "ALERT", text: summary },
    { kind: "TASK", text: currentTitle },
    { kind: "LOG", text: latest },
    { kind: "FIX", text: "优先处理恢复、生成恢复提示或进入系统设置。" },
  ];
  if (trust.level === "human") return [
    { kind: "STOP", text: "人工确认前自动化暂停。" },
    { kind: "TASK", text: currentTitle },
    { kind: "RISK", text: summary },
    { kind: "EVID", text: artifactSummary },
  ];
  if (trust.level === "high" || trust.level === "watch") return [
    { kind: "TASK", text: currentTitle },
    { kind: "STEP", text: summary },
    { kind: "LOG", text: latest },
    { kind: "OUT", text: artifactSummary },
  ];
  return [
    { kind: "READY", text: `${openClawAgentLabel(agent.id)} 在线待命。` },
    { kind: "NEXT", text: "可布置任务、打开开发台或查看技能。" },
    { kind: "LAST", text: latest },
    { kind: "EVID", text: artifactSummary },
  ];
}

function filterWorkbenchEvidenceEvents(events: WorkbenchEventRow[], item: WorkbenchTaskItem | null, agent: AgentWorkbenchAgent | null) {
  if (!events.length) return [];
  if (item) {
    const strongRows = events.filter((event) => eventMatchesWorkbenchItem(event, item));
    if (strongRows.length) return strongRows.slice(0, 24);
    return [];
  }
  if (agent) return events.filter((event) => event.agentId === agent.id).slice(0, 24);
  return events.slice(0, 24);
}

function eventMatchesWorkbenchItem(event: WorkbenchEventRow, item: WorkbenchTaskItem) {
  const payload = event.payload || {};
  const payloadValues = Object.values(payload)
    .filter((value) => typeof value === "string" || typeof value === "number")
    .map(String);
  const haystack = [
    event.id,
    event.workItemId,
    event.sourceId,
    event.agentId,
    event.eventType,
    event.message,
    ...payloadValues,
  ].filter(Boolean).join(" ");
  const taskPathName = item.taskPath?.split("/").filter(Boolean).pop() || "";
  const keys = [
    item.id,
    item.taskId,
    item.dbTaskId,
    item.sessionKey,
    item.taskPath,
    taskPathName,
    item.planPath,
    item.resultPath,
  ].filter((value): value is string => Boolean(value && String(value).length > 2));
  return keys.some((key) => haystack.includes(key));
}

function AgentEvidenceChain({ item, artifacts, eventRows, timeline, onPreviewReference }: {
  item: WorkbenchTaskItem | null;
  artifacts: Array<{ label: string; path: string; type: string; exists: boolean }>;
  eventRows: WorkbenchEventRow[];
  timeline: Array<{ type: string; actor: string; message: string; createdAt?: string }>;
  onPreviewReference: PreviewReferenceHandler;
}) {
  const latestEventLabel = eventRows[0]?.eventType || timeline[0]?.type || "";
  const latestEventCreatedAt = eventRows[0]?.createdAt || timeline[0]?.createdAt;
  const evidenceRows = [
    { key: "source", label: "来源", value: item?.source || "workbench", action: "" },
    { key: "agent", label: "代理", value: item?.agentId || "未选择", action: "" },
    { key: "updated", label: "最后活动", value: item?.lastActivityAt ? formatTaskTime(item.lastActivityAt) : "等待事件", action: "" },
    { key: "session", label: "Session", value: item?.sessionKey || item?.taskId || "未绑定", action: "" },
  ];
  const pathRows = [
    item?.planPath ? { label: "PLAN", path: item.planPath } : null,
    item?.resultPath ? { label: "RESULT", path: item.resultPath } : null,
    ...artifacts.slice(0, 2).map((artifact) => ({ label: artifact.label, path: artifact.path })),
  ].filter(Boolean) as Array<{ label: string; path: string }>;
  return <div className="agent-evidence-chain" aria-label="任务证据链">
    <div className="agent-evidence-chain-head">
      <strong>证据链</strong>
      <span>{latestEventLabel ? `${latestEventLabel} · ${formatTaskTime(latestEventCreatedAt)}` : "等待日志"}</span>
    </div>
    <div className="agent-evidence-chain-grid">
      {evidenceRows.map((row) => <div key={row.key}>
        <span>{row.label}</span>
        <strong>{row.value}</strong>
      </div>)}
    </div>
    {pathRows.length > 0 ? <div className="agent-evidence-chain-files">
      {pathRows.map((row) => <button key={`${row.label}:${row.path}`} type="button" onClick={() => onPreviewReference(row.path)}>
        <span>{row.label}</span>
        <strong>{row.path.split("/").pop() || row.path}</strong>
      </button>)}
    </div> : <p className="muted">还没有可点击的 PLAN/RESULT 或产出物。</p>}
  </div>;
}

function AgentArtifactPreview({ pathValue, label, planPath, resultPath, planContent, resultContent, exists, onPreviewReference }: {
  pathValue: string;
  label: string;
  planPath: string;
  resultPath: string;
  planContent: string;
  resultContent: string;
  exists: boolean;
  onPreviewReference: PreviewReferenceHandler;
}) {
  if (!pathValue) return <p className="muted">暂无可预览产物；等待 PLAN/RESULT、报告或文件生成。</p>;
  const ext = pathValue.split(/[?#]/)[0].split(".").pop()?.toLowerCase() || "";
  const isResult = resultPath && pathValue === resultPath;
  const isPlan = planPath && pathValue === planPath;
  const content = isResult ? resultContent : isPlan ? planContent : "";
  const href = workbenchFileHref(pathValue);
  if ((isResult || isPlan) && content) {
    return <div className="agent-evidence-rich-preview">
      <a href={href} target="_blank" rel="noreferrer">打开原文件</a>
      <MarkdownContent content={content} onPreviewReference={onPreviewReference} />
    </div>;
  }
  if (!exists) {
    return <div className="agent-evidence-missing-preview">
      <strong>{label || "产物文件"} 尚未生成</strong>
      <code>{pathValue}</code>
      <p>该工作项已声明产物路径，但磁盘上还没有对应文件。等代理写入 PLAN/RESULT 或刷新任务后会自动变为可预览。</p>
    </div>;
  }
  if (["png", "jpg", "jpeg", "webp", "gif"].includes(ext)) {
    return <div className="agent-evidence-rich-preview">
      <a href={href} target="_blank" rel="noreferrer">打开原文件</a>
      <img className="agent-evidence-preview-image" src={href} alt={label || pathValue} />
    </div>;
  }
  return <div className="agent-evidence-rich-preview">
    <a href={href} target="_blank" rel="noreferrer">打开原文件</a>
    <iframe className="agent-evidence-file-frame" src={href} title={label || pathValue} />
  </div>;
}

function workItemSidebarRank(item: WorkbenchTaskItem) {
  const text = `${item.status} ${item.phase}`.toLowerCase();
  if (isRecoveryWorkbenchItem(item)) return 0;
  if (isManualStopWorkbenchItem(item)) return 1;
  if (isObservableAutomationItem(item)) return 2;
  if (/created|queued/.test(text)) return 4;
  if (isCompletedWorkbenchItem(item)) return 8;
  return 5;
}

function uniqueArtifacts(rows: Array<{ label: string; path: string; type: string; exists: boolean }>) {
  const seen = new Set<string>();
  return rows.filter((row) => {
    const key = `${row.label}:${row.path}`;
    if (!row.path || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

