function RuntimeBar({ label, value, width }: { label: string; value: string; width: number }) {
  return <div className="agent-runtime-bar">
    <div><span>{label}</span><strong>{value}</strong></div>
    <i><b style={{ width: `${Math.max(8, Math.min(100, width))}%` }} /></i>
  </div>;
}

function isManualInterventionAttention(item: WorkbenchAttentionItem) {
  const text = `${item.title || ""} ${item.summary || ""} ${item.actionLabel || ""}`;
  return item.severity === "critical" || /待审批|审批|等待确认|确认|人工|介入|停滞|阻塞|恢复|诊断|暂不可用|不可用|超时|失败/.test(text);
}

function sortedAttentionRows(attention: WorkbenchAttentionItem[]) {
  return [...attention].sort((a, b) => {
    const aManual = isManualInterventionAttention(a) ? 1 : 0;
    const bManual = isManualInterventionAttention(b) ? 1 : 0;
    if (aManual !== bManual) return bManual - aManual;
    const rank = (item: WorkbenchAttentionItem) => item.severity === "critical" ? 3 : item.severity === "warn" ? 2 : 1;
    return rank(b) - rank(a);
  });
}

function AutonomyInterventionBoard({ attention, updatedAt, onSelectTask, onNavigate }: { attention: WorkbenchAttentionItem[]; updatedAt: string; onSelectTask: (id: string) => void; onNavigate: (page: Page) => void }) {
  const rows = sortedAttentionRows(attention);
  const manualRows = rows.filter((item) => isManualInterventionAttention(item));
  const stopped = manualRows.length > 0;
  const visibleRows = (stopped ? manualRows : rows).slice(0, 4);
  function openAttention(item: WorkbenchAttentionItem) {
    if (item.workItemId) {
      onSelectTask(item.workItemId);
      return;
    }
    const target = `${item.title || ""} ${item.summary || ""} ${item.actionLabel || ""}`;
    if (/系统|gateway|恢复|诊断|不可用|失败|超时|blocked|failed|unavailable/i.test(target)) {
      onNavigate("system");
      return;
    }
    onNavigate("agent");
  }
  return <section className={stopped ? "autonomy-intervention-board stopped" : "autonomy-intervention-board running"} aria-label="自治介入状态">
    <div className="autonomy-intervention-copy">
      <span>{stopped ? "人工介入 = 自治停机点" : "高自治运行"}</span>
      <h2>{stopped ? `${manualRows.length} 个节点等待人工处理` : "无需人工介入"}</h2>
      <p>{stopped ? "这些节点会降低智能体自动化效率，应优先处理或生成恢复提示。" : "代理可继续自主运行；人工只需要关注异常、审批和恢复点。"}</p>
    </div>
    <div className="autonomy-stop-list">
      <div className="attention-head"><strong>{stopped ? "待处理停机点" : "运行观察"}</strong><span>{updatedAt}</span></div>
      {visibleRows.length === 0 ? <p className="muted">没有需要人工处理的停机点。</p> : visibleRows.map((item) => <button
        key={item.id}
        type="button"
        className={`autonomy-stop-item ${item.severity}`}
        onClick={() => openAttention(item)}
      >
        <span>{item.title}</span>
        <strong>{item.summary}</strong>
        <small>{item.agentId || "system"} · {item.actionLabel || "查看"} · {formatTaskTime(item.createdAt)}</small>
      </button>)}
    </div>
  </section>;
}

