  async function runKnowledgeSearch(rawQuery: string) {
    const requestedSources = ["njx-knowledge", "memory", "wiki", "nas", "ima"].filter((source) => rawQuery.includes(`@${source}`));
    const searchText = rawQuery.replace(/@(njx-knowledge|all|memory|wiki|nas|ima)/g, "").trim();
    const sourceParam = requestedSources.length ? requestedSources.join(",") : "njx-knowledge,memory,wiki,nas,ima";
    setQuery(rawQuery);
    const data = await api<any>(`/api/knowledge/search?q=${encodeURIComponent(searchText)}&sources=${sourceParam}`);
    setResults(sortByRelevance(data.results || [], searchText));
  }
