  async function askPreviewQuestion(question: string) {
    const trimmed = question.trim();
    if (!selectedPath || !trimmed) return;
    const userMessage: KnowledgeChatMessage = { id: localId(), role: "user", content: trimmed, createdAt: new Date().toISOString() };
    const pendingId = localId();
    setKnowledgeMessages((rows) => [...rows, userMessage, { id: pendingId, role: "assistant", title: "ima", content: "正在阅读当前文件并生成回答...", createdAt: new Date().toISOString() }]);
    setAgentBusy(true);
    try {
      const data = await api<any>("/api/knowledge/preview-chat", { method: "POST", body: JSON.stringify({ sourcePath: selectedPath, question: trimmed, agentId: knowledgeAgentId }) });
      setPreviewAnswer(data.chat);
      setKnowledgeMessages((rows) => rows.map((row) => row.id === pendingId ? { ...row, content: data.chat?.answer || "已生成回答。", title: data.chat?.question || trimmed } : row));
    } catch (err) {
      setKnowledgeMessages((rows) => rows.map((row) => row.id === pendingId ? { ...row, content: err instanceof Error ? err.message : String(err), title: "请求失败" } : row));
    } finally {
      setAgentBusy(false);
    }
  }
