    setUpload({ name: "", content: "" });
    setKnowledgeMessages((rows) => [...rows, { id: localId(), role: "system", title: "快速录入", content: `已上传 sidecar：${data.upload?.title || upload.name || "upload.md"}\nWiki 嵌入：${knowledgeAtlasCompileStatusLabel(data.wikiCompile)}`, createdAt: new Date().toISOString() }]);
    setTick((v) => v + 1);
