  async function importKnowledgeFiles(files: File[], targetFolderPath = "") {
    if (!files.length) return;
    setFileActionBusy(true);
    setFileActionError("");
    try {
      const payloadFiles = await Promise.all(files.map(async (file) => ({
        name: file.name,
        mime: file.type,
        size: file.size,
        contentBase64: await fileToBase64(file),
      })));
      const data = await api<any>("/api/knowledge/files/import", {
        method: "POST",
        body: JSON.stringify({ targetFolderPath, files: payloadFiles }),
      });
      setTick((v) => v + 1);
      if (targetFolderPath) setExpandedPaths((rows) => rows.includes(targetFolderPath) ? rows : [...rows, targetFolderPath]);
      const firstPath = data.files?.[0]?.path;
      if (firstPath) {
        setSelectedPath(firstPath);
        setPreviewAnswer(null);
      }
      setKnowledgeMessages((rows) => [...rows, { id: localId(), role: "system", title: "文件导入", content: `已导入 ${data.files?.length || files.length} 个文件。\nWiki 嵌入：${knowledgeAtlasCompileStatusLabel(data.wikiCompile)}`, createdAt: new Date().toISOString() }]);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      setFileActionError(message);
      setKnowledgeMessages((rows) => [...rows, { id: localId(), role: "system", title: "文件导入失败", content: message, createdAt: new Date().toISOString() }]);
    } finally {
      setFileActionBusy(false);
      setDropTargetPath("");
    }
  }
  async function moveKnowledgeFiles(pathValues: string[], targetFolderPath: string) {
    const uniquePaths = Array.from(new Set(pathValues.map((pathValue) => String(pathValue || "").trim()).filter(Boolean)));
    if (!uniquePaths.length || !targetFolderPath) return;
    setFileActionBusy(true);
    setFileActionError("");
    try {
      const movedFiles: any[] = [];
      for (const pathValue of uniquePaths) {
        const data = await api<any>("/api/knowledge/files/move", { method: "POST", body: JSON.stringify({ path: pathValue, targetFolderPath }) });
        if (data.file) movedFiles.push(data.file);
      }
      const movedPathMap = new Map(movedFiles.map((file) => [String(file.oldPath || ""), String(file.path || "")]));
      setTick((v) => v + 1);
      setExpandedPaths((rows) => rows.includes(targetFolderPath) ? rows : [...rows, targetFolderPath]);
      setCheckedSourcePaths((rows) => {
        const next = new Set(rows);
        for (const pathValue of uniquePaths) next.delete(pathValue);
        for (const file of movedFiles) {
          const oldPath = String(file.oldPath || "");
          const newPath = String(file.path || "");
          if (oldPath && newPath && rows.includes(oldPath)) next.add(newPath);
        }
        return Array.from(next);
      });
      if (uniquePaths.includes(selectedPath)) {
        setSelectedPath(movedPathMap.get(selectedPath) || movedFiles[0]?.path || selectedPath);
        setPreviewAnswer(null);
      }
      setKnowledgeMessages((rows) => [...rows, { id: localId(), role: "system", title: "文件移动", content: `已移动 ${movedFiles.length || uniquePaths.length} 个文件。`, createdAt: new Date().toISOString() }]);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      setFileActionError(message);
      setKnowledgeMessages((rows) => [...rows, { id: localId(), role: "system", title: "文件移动失败", content: message, createdAt: new Date().toISOString() }]);
    } finally {
      setFileActionBusy(false);
      setDropTargetPath("");
    }
  }
  async function moveKnowledgeFile(pathValue: string, targetFolderPath: string) {
    await moveKnowledgeFiles([pathValue], targetFolderPath);
  }
