function OpcAutomationTab({
  dashboard,
  onRun,
  onPolicy,
  onIntegration,
  onIntegrationTest,
  onApproval,
  onQueueTodo,
  onOpenTab,
}: {
  dashboard: any;
  onRun: () => Promise<void>;
  onPolicy: (patch: Record<string, unknown>) => Promise<void>;
  onIntegration: (provider: string, body: Record<string, unknown>) => Promise<void>;
  onIntegrationTest: (provider: string, mode?: string) => Promise<void>;
  onApproval: (approvalId: string, decision: "approved" | "rejected") => Promise<void>;
  onQueueTodo: (item: any) => Promise<void>;
  onOpenTab: (tab: string) => void;
}) {
  const policy = dashboard.policy || {};
  const [drafts, setDrafts] = useState<Record<string, any>>({});
  function draftFor(row: any) {
    return {
      mode: row.mode || "dry_run",
      key_ref: row.key_ref || row.definition?.requiredKeyRef || "",
      credential_configured: Number(row.credential_configured || 0) === 1,
      scopes: Array.isArray(row.scopesList) ? row.scopesList.join(", ") : String(row.scopes || ""),
      notes: row.notes || row.definition?.note || "",
      ...(drafts[row.provider] || {}),
    };
  }
  function setDraft(provider: string, patch: Record<string, unknown>) {
    setDrafts((current) => ({ ...current, [provider]: { ...(current[provider] || {}), ...patch } }));
  }
  async function saveIntegration(row: any) {
    const draft = draftFor(row);
    await onIntegration(row.provider, {
      mode: draft.mode,
      key_ref: draft.key_ref,
      credential_configured: Boolean(draft.credential_configured),
      scopes: String(draft.scopes || "").split(",").map((item) => item.trim()).filter(Boolean),
      notes: draft.notes,
    });
    setDrafts((current) => ({ ...current, [row.provider]: undefined }));
  }
  return <div className="opc-resource-grid">
    <OpcAutomationGraph graph={dashboard.automationGraph} queue={dashboard.humanQueue || []} wide />
    <OpcHumanQueue rows={dashboard.humanQueue || []} onApproval={onApproval} onQueueTodo={onQueueTodo} onOpenTab={onOpenTab} />
    <section className="opc-section wide">
      <div className="opc-policy-strip">
        <label>模式<select value={policy.mode || "dry_run"} onChange={(e) => onPolicy({ mode: e.target.value })}><option value="dry_run">dry_run</option><option value="live">live</option></select></label>
        <label>预算 USD<input value={policy.budget_usd || 3289} onChange={(e) => onPolicy({ budget_usd: e.target.value })} /></label>
        <span>Live 模式必须先配置官方凭证、预算和动作权限；未配置时自动暂停。</span>
        <button type="button" onClick={onRun}>执行一轮自动运营</button>
      </div>
    </section>
    <section className="opc-section wide">
      <div className="opc-section-head"><h3>连接器配置</h3><span>只保存凭证引用，不保存密钥值</span></div>
      <div className="opc-connector-grid">
        {(dashboard.integrations || []).map((row: any) => {
          const draft = draftFor(row);
          const definition = row.definition || {};
          return <article className="opc-connector-card" key={row.provider}>
            <div className="opc-connector-card-head">
              <div>
                <strong>{definition.label || row.provider}</strong>
                <span>{definition.officialApi || "official API"}</span>
              </div>
              <OpcStatusChip value={row.status} />
            </div>
            <div className="opc-connector-fields">
              <label>模式<select aria-label={`${row.provider} 模式`} value={draft.mode} onChange={(event) => setDraft(row.provider, { mode: event.target.value })}><option value="dry_run">dry_run</option><option value="live">live</option></select></label>
              <label>凭证引用<input aria-label={`${row.provider} 凭证引用`} placeholder={definition.requiredKeyRef || "TOKEN_REF"} value={draft.key_ref} onChange={(event) => setDraft(row.provider, { key_ref: event.target.value })} /></label>
              <label>Scopes<input aria-label={`${row.provider} scopes`} value={draft.scopes} onChange={(event) => setDraft(row.provider, { scopes: event.target.value })} /></label>
              <label className="opc-check-line"><input aria-label={`${row.provider} 凭证已配置`} type="checkbox" checked={Boolean(draft.credential_configured)} onChange={(event) => setDraft(row.provider, { credential_configured: event.target.checked })} /><span>凭证已配置</span></label>
            </div>
            <textarea aria-label={`${row.provider} 连接器备注`} value={draft.notes} onChange={(event) => setDraft(row.provider, { notes: event.target.value })} />
            <div className="opc-connector-meta">
              <span>{row.credential_hint || "等待配置凭证引用"}</span>
              {row.last_error ? <span className="risk">{row.last_error}</span> : null}
              <span>{definition.note || row.notes}</span>
            </div>
            <div className="button-row">
              <button type="button" onClick={() => saveIntegration(row)}>保存配置</button>
              <button type="button" className="secondary" onClick={() => onIntegrationTest(row.provider, draft.mode)}>测试连接</button>
            </div>
          </article>;
        })}
      </div>
    </section>
    <section className="opc-section">
      <h3>自动化审计</h3>
      <OpcCompactTable rows={dashboard.automationRuns || []} empty="暂无自动化记录" columns={[
        { key: "action", label: "动作" },
        { key: "status", label: "状态", render: (row) => <OpcStatusChip value={row.status} /> },
        { key: "mode", label: "模式" },
        { key: "summary", label: "摘要" },
      ]} />
    </section>
    <section className="opc-section wide">
      <h3>同步记录</h3>
      <OpcCompactTable rows={dashboard.syncRuns || []} empty="暂无同步记录" columns={[
        { key: "provider", label: "平台" },
        { key: "status", label: "状态", render: (row) => <OpcStatusChip value={row.status} /> },
        { key: "records_read", label: "读取" },
        { key: "records_written", label: "写入" },
        { key: "message", label: "消息" },
      ]} />
    </section>
  </div>;
}

