function System({ live, onNavigate }: { live: { snapshot: any; connected: boolean }; onNavigate: (page: Page) => void }) {
  const [opsRefresh, setOpsRefresh] = useState(0);
  const [section, setSection] = useState<"overview" | "ops" | "mobile" | "audit">("overview");
  const system = useApi<any>("/api/system", []);
  const systemOps = useApi<any>("/api/system-ops", [opsRefresh]);
  const review = useApi<any>("/api/config-review", []);
  const computerUse = useApi<any>("/api/computer-use/status", []);
  const computerAudit = useApi<any>("/api/computer-use/audit?limit=12", []);
  const computerApprovals = useApi<any>("/api/computer-use/approvals", []);
  const checks = review.data?.checks || [];
  const sources = review.data?.sources || system.data?.sources || {};
  const computerUseStatus = computerUse.data?.computerUse || system.data?.computerUse?.status;
  const warnings = checks.filter((check: any) => ["warn", "error", "unknown"].includes(check.status));
  return <PageFrame title="系统设置" subtitle="System：OpenClaw 运维总控、健康状态、配置评审、连接器、资源和审计">
    <div className="system-section-tabs panel" role="tablist" aria-label="系统设置分区">
      {[
        ["overview", "系统总览", "原总览内容已合并到这里"],
        ["ops", "运维设置", "配置评审、连接器、Computer Use"],
        ["mobile", "手机配对", "iPhone / Android 配对管理"],
        ["audit", "资源审计", "资源、通知与审计日志"],
      ].map(([id, label, hint]) => <button
        type="button"
        key={id}
        className={section === id ? "active" : ""}
        onClick={() => setSection(id as typeof section)}
      >
        <strong>{label}</strong>
        <span>{hint}</span>
      </button>)}
    </div>
    {section === "overview" ? <>
      <SystemOpsOverviewStrip state={systemOps} onOpenOps={() => setSection("ops")} onRefresh={() => setOpsRefresh((value) => value + 1)} />
      <section className="system-embedded-overview"><Overview live={live} onNavigate={onNavigate} /></section>
    </> : null}
    {section === "ops" ? <>
      <StatusRow state={system} />
      <SystemOpsConsole state={systemOps} onRefresh={() => setOpsRefresh((value) => value + 1)} />
      <StatusRow state={review} />
      <div className="system-health-grid">
        <Metric label="Gateway" value={review.data?.gateway?.health?.status || system.data?.gateway?.status || "checking"} />
        <Metric label="Memory" value={sources.memory?.status || "-"} />
        <Metric label="NAS" value={sources.nas?.status || "-"} />
        <Metric label="IMA" value={sources.ima?.status || "-"} />
        <Metric label="Agents" value={String(review.data?.agents?.length || 0)} />
        <Metric label="Warnings" value={String(warnings.length)} />
        <Metric label="Computer Use" value={computerUseStatus?.ok ? "native" : (computerUseStatus?.capabilities?.pointer || "checking")} />
        <Metric label="Workspace" value={shortPath(system.data?.workspace)} />
        <Metric label="Generated" value={(review.data?.generatedAt || "-").slice(0, 16)} />
      </div>
      <div className={warnings.length ? "dashboard-alert-strip warn" : "dashboard-alert-strip ok"}>
        <div>
          <strong>系统告警</strong>
          <span>{warnings.length ? `${warnings.length} 项配置或连接需要关注` : "核心系统状态无阻塞告警"}</span>
        </div>
        <div className="dashboard-alert-list">
          {(warnings.length ? warnings : [{ category: "system", name: "OpenClaw Workbench", status: "ok", summary: "系统处于可观察状态" }]).slice(0, 8).map((check: any) => <div className={`alert-chip ${check.status}`} key={`${check.category}-${check.name}`}>
            <strong>{check.name}</strong>
            <span>{check.summary}</span>
          </div>)}
        </div>
      </div>
      <div className="grid two">
        <ReviewChecks checks={checks} />
        <AgentReview agents={review.data?.agents || []} />
        <SystemSourcesCard sources={sources} />
        <SystemConnectorCard checks={checks} />
        <ComputerUseCard status={computerUseStatus} auditRows={computerAudit.data?.rows || system.data?.computerUse?.recentActions || []} approvals={computerApprovals.data?.approvals || []} />
      </div>
    </> : null}
    {section === "mobile" ? <MobilePairingPage embedded /> : null}
    {section === "audit" ? <div className="grid two">
      <DataCard title="资源" data={review.data?.resources} />
      <ListCard title="通知" rows={system.data?.notifications || []} />
      <ListCard title="审计日志" rows={system.data?.audit || []} />
    </div> : null}
  </PageFrame>;
}

function SystemOpsOverviewStrip({ state, onOpenOps, onRefresh }: { state: ApiState<any>; onOpenOps: () => void; onRefresh: () => void }) {
  const data = state.data || {};
  const autonomy = data.autonomy || {};
  const defaultModel = data.models?.default || {};
  const maturity = autonomy.autonomyMaturity || {};
  const report = data.latestReport?.data || {};
  const incidentCoverage = autonomy.incidentCoverage || {};
  const finalDry = autonomy.finalDeliveryNoSendDryRun || {};
  const imessageChallenge = autonomy.imessageReceiveChallenge || {};
  const imessageAcceptance = imessageChallenge.acceptancePacket || {};
  const imessageReceivePlan = autonomy.imessageReceiveRepairPlan || {};
  const gatewayRpcHandoff = autonomy.gatewayRpcRecoveryHandoff || {};
  const gatewayRpcPlan = autonomy.gatewayRpcRecoveryPlan || {};
  const knowledgeNoteReliability = data.knowledgeNoteReliability || {};
  const workbenchHealthRecovery = data.workbenchHealthRecovery?.data || autonomy.workbenchHealthRecovery || {};
  const degraded = Array.isArray(maturity.degraded) ? maturity.degraded : [];
  return <section className="system-ops-overview-strip" id="system-ops-overview">
    <div className="system-ops-overview-head">
      <div>
        <span>Worker System Ops</span>
        <h2>系统运维台</h2>
        <p>Worker 主动巡检、被动接单和自治修复；Main 保留高风险审批与最终验收。</p>
      </div>
      <div className="system-ops-overview-actions">
        <button type="button" onClick={onOpenOps}>查看运维台</button>
        <button type="button" className="secondary" onClick={onOpenOps}>安排运维任务</button>
        <button type="button" className="ghost" onClick={onRefresh}>刷新</button>
      </div>
    </div>
    {state.loading ? <div className="notice skeleton">Worker 运维状态加载中</div> : state.error ? <div className="notice error">{state.error}</div> : <>
      <div className="system-ops-overview-kpis">
        <Metric label="Maturity" value={maturity.level || autonomy.status || "unknown"} />
        <Metric label="Model" value={defaultModel.label || defaultModel.model || "MiniMax M3"} />
        <Metric label="Score" value={maturity.score == null ? "-" : `${maturity.score}/100`} />
        <Metric label="Blockers" value={maturity.blockerCount == null ? "-" : String(maturity.blockerCount)} />
        <Metric label="Network" value={data.network?.status || report.network_status || "unknown"} />
        <Metric label="NAS" value={data.nas?.status || report.nas_status || "unknown"} />
        <Metric label="iMessage" value={autonomy.imessageReceiveLatest?.status || report.imessage_receive_status || "unknown"} />
        <Metric label="iMsg Challenge" value={imessageChallenge.status || "unknown"} />
        <Metric label="iMsg Plan" value={imessageReceivePlan.status || "unknown"} />
        <Metric label="Gateway RPC" value={gatewayRpcHandoff.status || "unknown"} />
        <Metric label="RPC Plan" value={gatewayRpcPlan.status || "unknown"} />
        <Metric label="Workbench" value={workbenchHealthRecovery.status || "unknown"} />
        <Metric label="Add Note" value={knowledgeNoteReliability.successRateLabel || knowledgeNoteReliability.status || "unknown"} />
        <Metric label="Incidents" value={incidentCoverage.uncovered == null ? "-" : `${incidentCoverage.covered ?? 0}/${(incidentCoverage.covered ?? 0) + (incidentCoverage.uncovered ?? 0)}`} />
        <Metric label="Final Dry" value={finalDry.ok == null ? "-" : `${finalDry.ok}/${finalDry.total ?? finalDry.ok}`} />
      </div>
      <div className={maturity.blockerCount ? "system-ops-overview-note warn" : degraded.length ? "system-ops-overview-note degraded" : "system-ops-overview-note ok"}>
        <strong>{maturity.blockerCount ? `${maturity.blockerCount} 个自治阻塞` : degraded.length ? "自治可运行但有真实降级" : "Worker 自治无阻塞"}</strong>
        <span>{maturity.blockerCount ? (maturity.blockers || []).slice(0, 2).join("; ") : degraded[0] || "所有核心运维门槛当前通过"}</span>
      </div>
      {imessageAcceptance.challengeText ? <div className="system-ops-overview-note warn">
        <strong>iMessage 入站验收：{imessageAcceptance.challengeText}</strong>
        <span>{imessageAcceptance.exactUserInstruction || "等待 iPhone 发送挑战文本；Worker 不能自发伪造入站。"}</span>
      </div> : null}
      {imessageReceivePlan.status === "WAITING_FOR_HUMAN_INBOUND" ? <div className="system-ops-overview-note warn">
        <strong>iMessage 等待真人入站</strong>
        <span>{imessageReceivePlan.summary || "通道、watcher 和 Messages DB 可观测；等待白名单 iPhone 新消息。"}</span>
      </div> : null}
      {gatewayRpcHandoff.status === "READY_FOR_MAIN_APPROVAL" ? <div className="system-ops-overview-note warn">
        <strong>Gateway RPC 恢复待 Main 审批</strong>
        <span>{gatewayRpcHandoff.gateway?.rootCauses?.[0] || gatewayRpcHandoff.summary || "Gateway HTTP live but RPC degraded"}</span>
      </div> : null}
      {gatewayRpcPlan.status === "READY_FOR_APPROVAL" ? <div className="system-ops-overview-note warn">
        <strong>Gateway RPC 恢复计划已生成</strong>
        <span>{gatewayRpcPlan.recoveryPlan?.approvalGate?.token || gatewayRpcPlan.summary || "等待 Main/用户审批后才能执行备份、重启、验证和回滚流程。"}</span>
      </div> : null}
      {workbenchHealthRecovery.status && workbenchHealthRecovery.status !== "OK" ? <div className={workbenchHealthRecovery.status === "RECOVERED" ? "system-ops-overview-note degraded" : "system-ops-overview-note warn"}>
        <strong>Workbench 本地服务：{workbenchHealthRecovery.status}</strong>
        <span>action={workbenchHealthRecovery.recoveryAction || "unknown"} · started={String(Boolean(workbenchHealthRecovery.safety?.workbenchServerStarted))} · confidence={workbenchHealthRecovery.healthConfidence || "unknown"}</span>
      </div> : null}
      {knowledgeNoteReliability.belowTarget ? <div className="system-ops-overview-note warn">
        <strong>添加笔记可靠性未达 {knowledgeNoteReliability.targetLabel || "99.99%"}</strong>
        <span>{knowledgeNoteReliability.code || "knowledge_note_reliability_below_target"} · {knowledgeNoteReliability.successRateLabel || "-"} · {knowledgeNoteReliability.total ?? 0} 个样本，{knowledgeNoteReliability.failed ?? 0} 失败，{knowledgeNoteReliability.aborted ?? 0} 中止。</span>
      </div> : null}
    </>}
  </section>;
}

function SystemOpsConsole({ state, onRefresh }: { state: ApiState<any>; onRefresh: () => void }) {
  const [busy, setBusy] = useState("");
  const [message, setMessage] = useState("");
  const data = state.data || {};
  const report = data.latestReport?.data || {};
  const risks = Array.isArray(data.risks) ? data.risks : [];
  const tasks = Array.isArray(data.tasks) ? data.tasks : [];
  const permissions = data.permissions || {};
  const defaultModel = data.models?.default || {};
  const cron = data.cron || {};
  const cronSession = data.cronSession || {};
  const activeRunner = data.activeRunner || {};
  const hostSupervisor = data.hostSupervisor || {};
  const autonomy = data.autonomy || {};
  const maturity = autonomy.autonomyMaturity || {};
  const mainReview = autonomy.mainReview || {};
  const reviewPackets = Array.isArray(mainReview.packets) ? mainReview.packets : [];
  const finalApproval = data.finalApproval || autonomy.finalApproval || {};
  const finalPackets = Array.isArray(finalApproval.packets) ? finalApproval.packets : [];
  const imessageChallenge = autonomy.imessageReceiveChallenge || {};
  const imessageChallengeData = imessageChallenge.challenge || {};
  const imessageAcceptance = imessageChallenge.acceptancePacket || {};
  const imessageAllowedHandles = Array.isArray(imessageAcceptance.allowedSenderHandlesRedacted) ? imessageAcceptance.allowedSenderHandlesRedacted : [];
  const imessageForbiddenActions = Array.isArray(imessageAcceptance.forbiddenActions) ? imessageAcceptance.forbiddenActions : [];
  const imessageReceivePlan = autonomy.imessageReceiveRepairPlan || {};
  const imessageReceivePlanData = imessageReceivePlan.repairPlan || {};
  const imessageReceivePlanPhases = Array.isArray(imessageReceivePlanData.phases) ? imessageReceivePlanData.phases : [];
  const imessageReceivePlanForbiddenActions = Array.isArray(imessageReceivePlanData.forbiddenActions) ? imessageReceivePlanData.forbiddenActions : [];
  const imessageReceivePlanReportPath = autonomy.imessageReceiveRepairPlanMarkdownPath || autonomy.imessageReceiveRepairPlanReportPath;
  const gatewayRpcHandoff = autonomy.gatewayRpcRecoveryHandoff || {};
  const gatewayRpcApproval = gatewayRpcHandoff.approvalPacket || {};
  const gatewayRpcForbiddenActions = Array.isArray(gatewayRpcApproval.forbiddenActions) ? gatewayRpcApproval.forbiddenActions : [];
  const gatewayRpcSafeProcedure = Array.isArray(gatewayRpcApproval.safeProcedure) ? gatewayRpcApproval.safeProcedure : [];
  const gatewayRpcReportPath = autonomy.gatewayRpcRecoveryHandoffMarkdownPath || autonomy.gatewayRpcRecoveryHandoffReportPath;
  const gatewayRpcPlan = autonomy.gatewayRpcRecoveryPlan || {};
  const gatewayRpcPlanData = gatewayRpcPlan.recoveryPlan || {};
  const gatewayRpcPlanApproval = gatewayRpcPlanData.approvalGate || {};
  const gatewayRpcPlanPreconditions = Array.isArray(gatewayRpcPlanData.preconditions) ? gatewayRpcPlanData.preconditions : [];
  const gatewayRpcPlanPhases = Array.isArray(gatewayRpcPlanData.phases) ? gatewayRpcPlanData.phases : [];
  const gatewayRpcPlanForbiddenActions = Array.isArray(gatewayRpcPlanData.forbiddenActions) ? gatewayRpcPlanData.forbiddenActions : [];
  const gatewayRpcPlanReportPath = autonomy.gatewayRpcRecoveryPlanMarkdownPath || autonomy.gatewayRpcRecoveryPlanReportPath;
  const knowledgeNoteReliability = data.knowledgeNoteReliability || {};
  const workbenchHealthRecovery = data.workbenchHealthRecovery?.data || autonomy.workbenchHealthRecovery || {};
  const workbenchHealthRecoveryPath = data.workbenchHealthRecovery?.latestMdPath || data.workbenchHealthRecovery?.path || autonomy.workbenchHealthRecoveryReportPath;
  const knowledgeNoteReliabilityLearning = data.knowledgeNoteReliabilityLearning?.data || {};
  const knowledgeNoteLearningCandidate = knowledgeNoteReliabilityLearning.candidate || {};
  const knowledgeNoteLearningArtifacts = knowledgeNoteReliabilityLearning.artifacts || {};
  const knowledgeNoteRecentJobs = Array.isArray(knowledgeNoteReliability.recentJobs) ? knowledgeNoteReliability.recentJobs : [];
  const knowledgeNoteFailureReasons = Array.isArray(knowledgeNoteReliability.topFailureReasons) ? knowledgeNoteReliability.topFailureReasons : [];
  const imessageAcceptancePath = autonomy.imessageReceiveChallengeMarkdownPath
    || imessageChallenge.reportPaths?.taskMd
    || imessageChallenge.reportPaths?.latestMd
    || autonomy.imessageReceiveChallengeReportPath;

  async function runShadow() {
    setBusy("shadow");
    setMessage("");
    try {
      const result = await api<any>("/api/system-ops/watchdog/run", { method: "POST", body: JSON.stringify({ mode: "shadow" }) });
      setMessage(`shadow 巡检完成：${result.result?.parsed?.status || result.result?.status || "unknown"}`);
      onRefresh();
    } catch (err) {
      setMessage(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy("");
    }
  }

  async function createTask() {
    setBusy("task");
    setMessage("");
    try {
      const result = await api<any>("/api/system-ops/tasks", {
        method: "POST",
        body: JSON.stringify({
          title: "系统运维巡检与风险处理",
          description: "从系统运维台创建：请 worker 根据最新 watchdog 报告、Cron、NAS、网络、Computer Use 权限状态执行低风险巡检；涉及 gateway 重启、配置写入、外部通知或受保护路径操作时升级给 Main。",
          priority: "P1",
          riskLevel: "normal",
        }),
      });
      setMessage(`已创建 worker 运维任务：${result.workbenchItem?.id || result.task?.id || "created"}`);
      onRefresh();
    } catch (err) {
      setMessage(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy("");
    }
  }

  async function decideMainReview(reviewId: string, decision: "approve_shadow" | "defer" | "reject") {
    setBusy(`review-${reviewId}-${decision}`);
    setMessage("");
    try {
      const result = await api<any>(`/api/system-ops/main-review/${encodeURIComponent(reviewId)}/decision`, {
        method: "POST",
        body: JSON.stringify({ decision, consume: true }),
      });
      const summary = result.consumer?.parsed?.summary;
      setMessage(`Main review 已记录：${result.reviewId} / ${result.decision}。消费器：${result.consumer?.parsed?.status || "skipped"}，shadow ready ${summary?.shadowReady ?? 0}。`);
      onRefresh();
    } catch (err) {
      setMessage(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy("");
    }
  }

  async function consumeMainReview() {
    setBusy("review-consume");
    setMessage("");
    try {
      const result = await api<any>("/api/system-ops/main-review/consume", { method: "POST", body: JSON.stringify({}) });
      const summary = result.result?.parsed?.summary;
      setMessage(`审批消费完成：${result.result?.parsed?.status || result.result?.status || "unknown"}，waiting ${summary?.waiting ?? "-"}，shadow ready ${summary?.shadowReady ?? "-"}`);
      onRefresh();
    } catch (err) {
      setMessage(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy("");
    }
  }

  async function decideFinalApproval(finalReviewId: string, decision: "approve_plan" | "defer" | "reject") {
    setBusy(`final-${finalReviewId}-${decision}`);
    setMessage("");
    try {
      const result = await api<any>(`/api/system-ops/final-approval/${encodeURIComponent(finalReviewId)}/decision`, {
        method: "POST",
        body: JSON.stringify({
          decision,
          consume: true,
          note: "Workbench System Ops final delivery gate. Approval only allows Worker to generate a local migration plan artifact.",
        }),
      });
      const summary = result.consumer?.parsed?.summary;
      setMessage(`Final Delivery 已记录：${result.finalReviewId} / ${result.decision}。消费器：${result.consumer?.parsed?.status || "skipped"}，plan ready ${summary?.planReady ?? 0}。`);
      onRefresh();
    } catch (err) {
      setMessage(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy("");
    }
  }

  async function consumeFinalApproval() {
    setBusy("final-consume");
    setMessage("");
    try {
      const result = await api<any>("/api/system-ops/final-approval/consume", { method: "POST", body: JSON.stringify({}) });
      const summary = result.result?.parsed?.summary;
      setMessage(`Final Delivery 消费完成：${result.result?.parsed?.status || result.result?.status || "unknown"}，waiting ${summary?.waiting ?? "-"}，plan ready ${summary?.planReady ?? "-"}`);
      onRefresh();
    } catch (err) {
      setMessage(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy("");
    }
  }

  return <section className="system-ops-console" id="system-ops">
    <div className="system-ops-sticky">
      <div>
        <span>Worker System Ops</span>
        <h2>系统运维台</h2>
        <p>Worker 负责主动巡检和被动接单；Main 保留高风险审批、配置变更验收和最终兜底。</p>
      </div>
      <div className="system-ops-actions">
        <button type="button" onClick={runShadow} disabled={busy === "shadow"}>{busy === "shadow" ? "巡检中" : "运行 shadow 巡检"}</button>
        <button type="button" className="secondary" onClick={createTask} disabled={busy === "task"}>{busy === "task" ? "创建中" : "安排运维任务"}</button>
      </div>
    </div>
    {state.loading ? <div className="notice skeleton">系统运维台加载中</div> : state.error ? <div className="notice error">{state.error}</div> : <>
      <div className="system-ops-kpis">
        <Metric label="Owner" value={data.ownerAgentId || "worker"} />
        <Metric label="Model" value={defaultModel.label || defaultModel.model || "MiniMax M3"} />
        <Metric label="Runner" value={activeRunner.label || "unknown"} />
        <Metric label="Watchdog" value={report.status || "unknown"} />
        <Metric label="Network" value={data.network?.status || "unknown"} />
        <Metric label="NAS" value={data.nas?.status || "unknown"} />
        <Metric label="AgentTurn" value={activeRunner.cronPaused ? "paused" : (cron.agentId ? `${cron.agentId} / ${cron.status || cron.lastStatus || "active"}` : "missing")} />
        <Metric label="Autonomy" value={autonomy.status || "unknown"} />
        <Metric label="Maturity" value={maturity.score == null ? "-" : `${maturity.score}`} />
        <Metric label="Computer" value={data.computerUse?.ok ? "native" : "degraded"} />
        <Metric label="Updated" value={(hostSupervisor.data?.generatedAt || data.generatedAt || "-").slice(5, 16)} />
        <Metric label="Learning" value={autonomy.learningScore == null ? "-" : String(autonomy.learningScore)} />
        <Metric label="Promotion" value={autonomy.promotionStatus || "-"} />
        <Metric label="Policy" value={autonomy.policyPromotionStatus || "-"} />
        <Metric label="Triage" value={autonomy.cronTriage?.queuedRepairs == null ? "-" : String(autonomy.cronTriage.queuedRepairs)} />
        <Metric label="Repair" value={autonomy.cronRepair?.diagnosed == null ? "-" : String(autonomy.cronRepair.diagnosed)} />
        <Metric label="Review" value={autonomy.mainReviewPackets?.total == null ? "-" : String(autonomy.mainReviewPackets.total)} />
        <Metric label="Contract" value={autonomy.shadowDesignValidation?.total == null ? "-" : String(autonomy.shadowDesignValidation.total)} />
        <Metric label="Final Gate" value={autonomy.finalApprovalPack?.finalReviewReady == null ? "-" : String(autonomy.finalApprovalPack.finalReviewReady)} />
        <Metric label="Final Plan" value={autonomy.finalApprovalConsumer?.planReady == null ? "-" : String(autonomy.finalApprovalConsumer.planReady)} />
        <Metric label="Final Dry" value={autonomy.finalDeliveryNoSendDryRun?.ok == null ? "-" : String(autonomy.finalDeliveryNoSendDryRun.ok)} />
        <Metric label="Sys Probe" value={autonomy.systemOpsProbe?.status || "-"} />
        <Metric label="Ops Cover" value={autonomy.systemOpsCoverageState?.status || "-"} />
        <Metric label="Gateway RPC" value={gatewayRpcHandoff.status || "-"} />
        <Metric label="RPC Plan" value={gatewayRpcPlan.status || "-"} />
        <Metric label="Workbench" value={workbenchHealthRecovery.status || "-"} />
        <Metric label="Add Note SLO" value={knowledgeNoteReliability.successRateLabel || "-"} />
        <Metric label="Note Takeover" value={knowledgeNoteReliability.supersededByLaterSuccess == null ? "-" : String(knowledgeNoteReliability.supersededByLaterSuccess)} />
        <Metric label="iMsg Challenge" value={imessageChallenge.status || "-"} />
        <Metric label="iMsg Plan" value={imessageReceivePlan.status || "-"} />
        <Metric label="Runner" value={autonomy.readyRepairRunner?.total == null ? "-" : String(autonomy.readyRepairRunner.total)} />
        <Metric label="Shadow" value={autonomy.readyRepairShadow?.total == null ? "-" : String(autonomy.readyRepairShadow.total)} />
        <Metric label="Incidents" value={autonomy.incidents == null ? "-" : String(autonomy.incidents)} />
      </div>
      <div className="system-ops-layout">
        <section className="system-ops-main">
          <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>Worker 运维报告</h3><p>{data.latestReport?.path || "暂无 system_ops_watchdog 报告"}</p></div>
              <StatusPill value={report.status || "unknown"} />
            </div>
            <div className="system-ops-summary">{report.summary || "暂无摘要；可先运行 shadow 巡检生成报告。"}</div>
            <div className="system-ops-mini-grid">
              <div><span>Active Runner</span><strong>{activeRunner.kind || "-"}</strong><small>{activeRunner.cronPaused ? "agentTurn paused" : "OpenClaw cron"}</small></div>
              <div><span>Host Supervisor</span><strong>{hostSupervisor.data?.ok ? "active" : "unknown"}</strong><small>{shortPath(hostSupervisor.path)}</small></div>
              <div><span>Clash</span><strong>{data.network?.clashAction || "-"}</strong><small>{data.network?.selectedRegion || "未选择"}</small></div>
              <div><span>NAS Path</span><strong>{shortPath(data.nas?.path)}</strong><small>{data.nas?.status || "unknown"}</small></div>
              <div><span>Resume</span><strong>{report.resume_action || "-"}</strong><small>{String(report.codex_error_detected ?? false)}</small></div>
              <div><span>Cron Transcript</span><strong>{cronSession.cronStatus || "-"}</strong><small>{activeRunner.cronPaused ? "paused by evidence" : shortPath(cronSession.transcriptPath)}</small></div>
            </div>
          </div>
          <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>添加笔记可靠性</h3><p>{shortPath(knowledgeNoteReliability.reportRoots?.jobs || "memory/reports/knowledge_note_organize_jobs")}</p></div>
              <StatusPill value={knowledgeNoteReliability.status || "unknown"} />
            </div>
            <div className="system-ops-summary">
              {knowledgeNoteReliability.code || "knowledge_note_reliability_observing"} · 近 {knowledgeNoteReliability.windowDays || 7} 天 {knowledgeNoteReliability.total ?? 0} 个 job，成功率 {knowledgeNoteReliability.successRateLabel || "-"}，同源接管 {knowledgeNoteReliability.supersededByLaterSuccess ?? 0}，未恢复 stale {knowledgeNoteReliability.unrecoveredStale ?? 0}，目标 {knowledgeNoteReliability.targetLabel || "99.99%"}{knowledgeNoteReliability.targetProven ? " 已证明" : " 未证明"}。
            </div>
            <div className="system-ops-mini-grid">
              <div><span>成功</span><strong>{knowledgeNoteReliability.succeeded ?? 0}</strong><small>可保存 Markdown + HTML</small></div>
              <div><span>失败</span><strong>{knowledgeNoteReliability.failed ?? 0}</strong><small>{knowledgeNoteReliability.aborted ?? 0} aborted</small></div>
              <div><span>运行中</span><strong>{knowledgeNoteReliability.running ?? 0}</strong><small>queued/running</small></div>
              <div><span>同源接管</span><strong>{knowledgeNoteReliability.supersededByLaterSuccess ?? 0}</strong><small>superseded success</small></div>
              <div><span>未恢复 stale</span><strong>{knowledgeNoteReliability.unrecoveredStale ?? 0}</strong><small>仍需 Worker 处理</small></div>
              <div><span>Ops Recovery</span><strong>{knowledgeNoteReliability.opsRecovery?.recovered ?? 0}/{knowledgeNoteReliability.opsRecovery?.total ?? 0}</strong><small>{shortPath(knowledgeNoteReliability.opsRecovery?.latestReportPath)}</small></div>
              <div><span>样本下限</span><strong>{knowledgeNoteReliability.sampleFloor ?? 10000}</strong><small>99.99% 证据门槛</small></div>
              <div><span>最近失败</span><strong>{knowledgeNoteReliability.latestFailure?.reason || knowledgeNoteReliability.latestFailure?.phase || "-"}</strong><small>{shortPath(knowledgeNoteReliability.latestFailure?.reportPath)}</small></div>
              <div><span>学习队列</span><strong>{knowledgeNoteLearningCandidate.queue_id || "QUEUE-KNOWLEDGE-NOTE-RELIABILITY-SLO"}</strong><small>{knowledgeNoteLearningCandidate.validation_status || "pending_worker_repair_validation"}</small></div>
              <div><span>Failure Case</span><strong>{knowledgeNoteLearningCandidate.priority || "-"}</strong><small>{shortPath(knowledgeNoteLearningCandidate.source_file || knowledgeNoteLearningArtifacts.failureCase)}</small></div>
              <div><span>Learning Report</span><strong>{knowledgeNoteReliabilityLearning.status || "-"}</strong><small>{shortPath(data.knowledgeNoteReliabilityLearning?.path || knowledgeNoteLearningArtifacts.latestReport)}</small></div>
            </div>
            <div className="system-ops-next-actions">
              {knowledgeNoteFailureReasons.length ? knowledgeNoteFailureReasons.slice(0, 4).map((item: any, index: number) => <div key={`note-reason-${index}`} className="compact-row warning">
                <strong>{item.reason}</strong>
                <span>{item.count} 次</span>
              </div>) : <div className="compact-row">
                <strong>暂无失败根因样本</strong>
                <span>继续采集真实 Gateway/MiniMax 添加笔记 job。</span>
              </div>}
              {knowledgeNoteRecentJobs.slice(0, 4).map((job: any) => <div key={job.id || job.reportPath} className={job.status === "succeeded" ? "compact-row" : "compact-row warning"}>
                <strong>{job.title || job.id || "添加笔记 job"}</strong>
                <span>{job.status} · {job.phase || "-"} · retry {job.retryUsed ?? "-"}/{job.retryMax ?? "-"} · html {job.htmlScore ?? "-"}</span>
                <small>{shortPath(job.reportPath)}</small>
              </div>)}
            </div>
          </div>
          <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>Workbench 本地服务守护</h3><p>{shortPath(workbenchHealthRecoveryPath || "memory/reports/worker_autonomy/LATEST_WORKER_WORKBENCH_HEALTH_RECOVERY.json")}</p></div>
              <StatusPill value={workbenchHealthRecovery.status || "unknown"} />
            </div>
            <div className="system-ops-summary">
              {workbenchHealthRecovery.cronStatus || "CRON_STATUS=unknown"} · mode={workbenchHealthRecovery.mode || "-"} · action={workbenchHealthRecovery.recoveryAction || "-"} · confidence={workbenchHealthRecovery.healthConfidence || "-"}。
            </div>
            <div className="system-ops-mini-grid">
              <div><span>Initial Health</span><strong>{workbenchHealthRecovery.initialHealth?.ok ? "ok" : "failed"}</strong><small>{workbenchHealthRecovery.initialHealth?.error || workbenchHealthRecovery.initialHealth?.status || "-"}</small></div>
              <div><span>Initial Listener</span><strong>{workbenchHealthRecovery.initialListener?.ok ? "listening" : "not listening"}</strong><small>{workbenchHealthRecovery.initialListener?.endpoint || "-"}</small></div>
              <div><span>Final Health</span><strong>{workbenchHealthRecovery.finalHealth?.ok ? "ok" : "failed"}</strong><small>{workbenchHealthRecovery.finalHealth?.error || workbenchHealthRecovery.finalHealth?.status || "-"}</small></div>
              <div><span>Final Listener</span><strong>{workbenchHealthRecovery.finalListener?.ok ? "listening" : "not listening"}</strong><small>{workbenchHealthRecovery.finalListener?.endpoint || "-"}</small></div>
              <div><span>Started</span><strong>{String(Boolean(workbenchHealthRecovery.safety?.workbenchServerStarted))}</strong><small>Workbench only</small></div>
              <div><span>Gateway Restart</span><strong>{String(Boolean(workbenchHealthRecovery.safety?.openclawGatewayRestarted))}</strong><small>must stay false</small></div>
              <div><span>Cron Mutation</span><strong>{String(Boolean(workbenchHealthRecovery.safety?.cronMutationExecuted))}</strong><small>must stay false</small></div>
              <div><span>External Send</span><strong>{String(Boolean(workbenchHealthRecovery.safety?.externalSendExecuted))}</strong><small>must stay false</small></div>
            </div>
            <div className="system-ops-next-actions">
              {(Array.isArray(workbenchHealthRecovery.nextActions) && workbenchHealthRecovery.nextActions.length ? workbenchHealthRecovery.nextActions : ["等待 Worker autonomy loop 生成 Workbench 本地服务守护报告。"]).slice(0, 4).map((item: string, index: number) => <div key={`workbench-health-next-${index}`} className={workbenchHealthRecovery.status === "OK" ? "compact-row" : "compact-row warning"}>
                <strong>{index === 0 ? "下一步" : `下一步 ${index + 1}`}</strong>
                <span>{item}</span>
              </div>)}
            </div>
          </div>
          <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>Worker 自治</h3><p>{autonomy.latestMdPath || data.workerAutonomy?.path || "暂无自治报告"}</p></div>
              <StatusPill value={autonomy.status || "unknown"} />
            </div>
            <div className="system-ops-mini-grid">
              <div><span>Cron Health</span><strong>{autonomy.cronStatus || "-"}</strong><small>{autonomy.autonomyScore == null ? "score -" : `autonomy ${autonomy.autonomyScore}`}</small></div>
              <div><span>Autonomy Maturity</span><strong>{maturity.level || "-"}</strong><small>{maturity.score == null ? "score -" : `${maturity.score}/100 · ${maturity.blockerCount ?? 0} blockers`}</small></div>
              <div><span>Learning</span><strong>{autonomy.learningScore == null ? "-" : autonomy.learningScore}</strong><small>self-improving loop</small></div>
              <div><span>Promotion</span><strong>{autonomy.promotionStatus || "-"}</strong><small>{autonomy.promotionPublished ? "published" : "not published"}</small></div>
              <div><span>Baseline</span><strong>{autonomy.promotionQueueId || "-"}</strong><small>{shortPath((autonomy.promotionBaselinePaths || [])[0] || autonomy.promotionReportPath)}</small></div>
              <div><span>Fake OK Policy</span><strong>{autonomy.policyPromotionStatus || "-"}</strong><small>{autonomy.policyPromotionPublished ? "published" : "not published"}</small></div>
              <div><span>Policy Queue</span><strong>{autonomy.policyPromotionQueueId || "-"}</strong><small>{shortPath((autonomy.policyPromotionBaselinePaths || [])[0] || autonomy.policyPromotionReportPath)}</small></div>
              <div><span>Cron Triage</span><strong>{autonomy.cronTriage?.appliedActions == null ? "-" : autonomy.cronTriage.appliedActions}</strong><small>{autonomy.cronTriage?.queuedRepairs == null ? "queued -" : `${autonomy.cronTriage.queuedRepairs} queued`}</small></div>
              <div><span>Cron Repair</span><strong>{autonomy.cronRepair?.diagnosed == null ? "-" : autonomy.cronRepair.diagnosed}</strong><small>{autonomy.cronRepair?.mainReviewRequired == null ? "review -" : `${autonomy.cronRepair.mainReviewRequired} main review`}</small></div>
              <div><span>Main Review</span><strong>{autonomy.mainReviewPackets?.total == null ? "-" : autonomy.mainReviewPackets.total}</strong><small>{autonomy.mainReviewPackets?.highRisk == null ? shortPath(autonomy.mainReviewPacketsReportPath) : `${autonomy.mainReviewPackets.highRisk} high risk`}</small></div>
              <div><span>Review Gate</span><strong>{mainReview.summary?.waiting == null ? "-" : mainReview.summary.waiting}</strong><small>{mainReview.summary?.shadowReady == null ? "waiting decisions" : `${mainReview.summary.shadowReady} shadow ready`}</small></div>
              <div><span>Shadow Contracts</span><strong>{autonomy.shadowDesignValidation?.total == null ? "-" : autonomy.shadowDesignValidation.total}</strong><small>{autonomy.shadowDesignValidation?.error == null ? shortPath(autonomy.shadowDesignValidationReportPath) : `${autonomy.shadowDesignValidation.error} errors`}</small></div>
              <div><span>Incident Coverage</span><strong>{autonomy.incidentCoverage?.covered == null ? "-" : autonomy.incidentCoverage.covered}</strong><small>{autonomy.incidentCoverage?.uncovered == null ? shortPath(autonomy.incidentCoverageReportPath) : `${autonomy.incidentCoverage.uncovered} uncovered`}</small></div>
              <div><span>Final Delivery Gate</span><strong>{autonomy.finalApprovalPack?.finalReviewReady == null ? "-" : autonomy.finalApprovalPack.finalReviewReady}</strong><small>{autonomy.finalApprovalPack?.highRisk == null ? shortPath(autonomy.finalApprovalPackReportPath) : `${autonomy.finalApprovalPack.highRisk} high risk`}</small></div>
              <div><span>Final Plan Consumer</span><strong>{autonomy.finalApprovalConsumer?.planReady == null ? "-" : autonomy.finalApprovalConsumer.planReady}</strong><small>{autonomy.finalApprovalConsumer?.waiting == null ? shortPath(autonomy.finalApprovalConsumerReportPath || autonomy.finalApprovalPlanDir) : `${autonomy.finalApprovalConsumer.waiting} waiting`}</small></div>
              <div><span>No-Send Dry Run</span><strong>{autonomy.finalDeliveryNoSendDryRun?.ok == null ? "-" : autonomy.finalDeliveryNoSendDryRun.ok}</strong><small>{autonomy.finalDeliveryNoSendDryRun?.jobsUnchanged == null ? shortPath(autonomy.finalDeliveryNoSendDryRunReportPath || autonomy.finalDeliveryNoSendDryRunDir) : `jobs unchanged ${String(autonomy.finalDeliveryNoSendDryRun.jobsUnchanged)}`}</small></div>
              <div><span>System Ops Probe</span><strong>{autonomy.systemOpsProbe?.status || "-"}</strong><small>{autonomy.systemOpsProbe?.network_status || shortPath(autonomy.systemOpsProbeReportPath)}</small></div>
              <div><span>System Ops Latest</span><strong>{autonomy.systemOpsLatest?.status || "-"}</strong><small>{autonomy.systemOpsLatest?.network_status || shortPath(autonomy.systemOpsLatest?.path)}</small></div>
              <div><span>System Ops Coverage</span><strong>{autonomy.systemOpsCoverageState?.status || "-"}</strong><small>{autonomy.systemOpsCoverageState?.reason || shortPath(autonomy.systemOpsCoverageReportPath)}</small></div>
              <div><span>Gateway RPC Handoff</span><strong>{gatewayRpcHandoff.status || "-"}</strong><small>{gatewayRpcHandoff.gateway?.rootCauses?.[0] || shortPath(gatewayRpcReportPath)}</small></div>
              <div><span>Gateway RPC Plan</span><strong>{gatewayRpcPlan.status || "-"}</strong><small>{gatewayRpcPlanData.approvalGate?.token || shortPath(gatewayRpcPlanReportPath)}</small></div>
              <div><span>iMessage Challenge</span><strong>{imessageChallenge.status || "-"}</strong><small>{imessageChallengeData.text || shortPath(autonomy.imessageReceiveChallengeReportPath)}</small></div>
              <div><span>iMessage Plan</span><strong>{imessageReceivePlan.status || "-"}</strong><small>{imessageReceivePlan.category || shortPath(imessageReceivePlanReportPath)}</small></div>
              <div><span>Challenge Freshness</span><strong>{imessageChallengeData.createdAt ? imessageChallengeData.createdAt.slice(11, 19) : "-"}</strong><small>{imessageChallengeData.lastExpectedAckStatus || imessageChallengeData.lastBlocker || shortPath(autonomy.imessageReceiveChallengeStatePath)}</small></div>
              <div><span>Ready Runner</span><strong>{autonomy.readyRepairRunner?.total == null ? "-" : autonomy.readyRepairRunner.total}</strong><small>{autonomy.readyRepairRunner?.degraded == null ? "degraded -" : `${autonomy.readyRepairRunner.degraded} degraded`}</small></div>
              <div><span>Ready Shadow</span><strong>{autonomy.readyRepairShadow?.total == null ? "-" : autonomy.readyRepairShadow.total}</strong><small>{autonomy.readyRepairShadow?.degraded == null ? "degraded -" : `${autonomy.readyRepairShadow.degraded} degraded`}</small></div>
              <div><span>Actions</span><strong>{autonomy.actions == null ? "-" : autonomy.actions}</strong><small>{autonomy.incidents == null ? "incidents -" : `${autonomy.incidents} incidents`}</small></div>
            </div>
            <div className="system-ops-next-actions">
              {Array.isArray(maturity.blockers) && maturity.blockers.length ? maturity.blockers.slice(0, 4).map((item: string, index: number) => <div key={`maturity-${item}-${index}`} className="compact-row warning">
                <strong>{item}</strong>
                <span>Autonomy maturity blocker</span>
              </div>) : null}
              {(Array.isArray(autonomy.nextActions) && autonomy.nextActions.length ? autonomy.nextActions : ["暂无下一步建议"]).map((item: string, index: number) => <div key={`${item}-${index}`} className="compact-row">
                <strong>{item}</strong>
                <span>Worker autonomy next action</span>
              </div>)}
            </div>
          </div>
          {gatewayRpcHandoff.status ? <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>Gateway RPC 恢复交接单</h3><p>{shortPath(gatewayRpcReportPath)}</p></div>
              <StatusPill value={gatewayRpcHandoff.status || "unknown"} />
            </div>
            <div className="system-ops-mini-grid">
              <div><span>RPC</span><strong>{gatewayRpcHandoff.gateway?.rpcOk ? "ok" : "degraded"}</strong><small>{gatewayRpcHandoff.gateway?.statusLabel || "-"}</small></div>
              <div><span>HTTP</span><strong>{gatewayRpcHandoff.gateway?.httpOk ? "live" : "failed"}</strong><small>{gatewayRpcHandoff.gateway?.processLive ? "process live" : "process unknown"}</small></div>
              <div><span>审批状态</span><strong>{gatewayRpcApproval.status || "-"}</strong><small>{gatewayRpcApproval.riskLevel || "high"}</small></div>
              <div><span>根因</span><strong>{gatewayRpcHandoff.gateway?.rootCauses?.[0] || "-"}</strong><small>{gatewayRpcHandoff.summary || "Gateway RPC handoff"}</small></div>
            </div>
            <div className="system-ops-next-actions">
              <div className="compact-row warning">
                <strong>{gatewayRpcApproval.requiredApproval || "Main/user approval required before Gateway restart."}</strong>
                <span>{gatewayRpcApproval.reason || gatewayRpcHandoff.gateway?.rootCauses?.[0] || "gateway_rpc_degraded"}</span>
              </div>
              {gatewayRpcSafeProcedure.slice(0, 4).map((item: string, index: number) => <div key={`gateway-rpc-safe-${index}`} className="compact-row">
                <strong>{item}</strong>
                <span>安全流程</span>
              </div>)}
              {gatewayRpcForbiddenActions.slice(0, 3).map((item: string, index: number) => <div key={`gateway-rpc-forbid-${index}`} className="compact-row warning">
                <strong>{item}</strong>
                <span>禁止动作</span>
              </div>)}
            </div>
          </div> : null}
          {gatewayRpcPlan.status ? <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>Gateway RPC 恢复计划</h3><p>{shortPath(gatewayRpcPlanReportPath)}</p></div>
              <StatusPill value={gatewayRpcPlan.status || "unknown"} />
            </div>
            <div className="system-ops-mini-grid">
              <div><span>审批令牌</span><strong>{gatewayRpcPlanApproval.token || "-"}</strong><small>{gatewayRpcPlanApproval.requiredBy || "Main/user approval"}</small></div>
              <div><span>风险</span><strong>{gatewayRpcPlanData.riskLevel || "high"}</strong><small>{gatewayRpcPlanApproval.reason || "Gateway restart gated"}</small></div>
              <div><span>根因</span><strong>{gatewayRpcPlanData.rootCause || "-"}</strong><small>{gatewayRpcPlan.summary || "safe recovery plan"}</small></div>
              <div><span>执行策略</span><strong>{gatewayRpcPlanApproval.required ? "approval required" : "not required"}</strong><small>{gatewayRpcPlanApproval.executionPolicy || "Worker does not execute restart"}</small></div>
            </div>
            <div className="system-ops-next-actions">
              {gatewayRpcPlanPreconditions.slice(0, 4).map((item: any, index: number) => <div key={`gateway-rpc-plan-pre-${index}`} className={item.ok ? "compact-row" : "compact-row warning"}>
                <strong>{item.id || "precondition"}</strong>
                <span>{item.evidence || (item.ok ? "ok" : "missing")}</span>
              </div>)}
              {gatewayRpcPlanPhases.slice(0, 5).map((phase: any, index: number) => <div key={`gateway-rpc-plan-phase-${index}`} className={phase.risk === "high" ? "compact-row warning" : "compact-row"}>
                <strong>{`${index + 1}. ${phase.id || "phase"} · ${phase.owner || "worker"} · ${phase.risk || "low"}`}</strong>
                <span>{phase.command || "-"}</span>
              </div>)}
              {gatewayRpcPlanForbiddenActions.slice(0, 3).map((item: string, index: number) => <div key={`gateway-rpc-plan-forbid-${index}`} className="compact-row warning">
                <strong>{item}</strong>
                <span>禁止动作</span>
              </div>)}
            </div>
          </div> : null}
          {imessageReceivePlan.status ? <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>iMessage 接收修复计划</h3><p>{shortPath(imessageReceivePlanReportPath)}</p></div>
              <StatusPill value={imessageReceivePlan.status || "unknown"} />
            </div>
            <div className="system-ops-mini-grid">
              <div><span>分类</span><strong>{imessageReceivePlan.category || "-"}</strong><small>{imessageReceivePlan.summary || "receive diagnosis"}</small></div>
              <div><span>Channel</span><strong>{imessageReceivePlanData.channelState?.running ? "running" : "unknown"}</strong><small>{imessageReceivePlanData.channelState?.configured ? "configured" : "not configured"}</small></div>
              <div><span>Watcher</span><strong>{imessageReceivePlanData.runtimeState?.wrapperRpcRunning ? "running" : "unknown"}</strong><small>{imessageReceivePlanData.runtimeState?.realImsgRpcRunning ? "real imsg rpc" : "rpc unknown"}</small></div>
              <div><span>Messages DB</span><strong>{imessageReceivePlanData.messagesDbState?.readable ? "readable" : "unknown"}</strong><small>{imessageReceivePlanData.messagesDbState?.latestAllowedInboundAgeHours == null ? "age -" : `${Math.round(imessageReceivePlanData.messagesDbState.latestAllowedInboundAgeHours)}h allowlisted`}</small></div>
            </div>
            <div className="system-ops-next-actions">
              {imessageReceivePlanPhases.slice(0, 4).map((phase: any, index: number) => <div key={`imsg-plan-phase-${index}`} className={phase.risk === "manual_permission_or_account" ? "compact-row warning" : "compact-row"}>
                <strong>{`${index + 1}. ${phase.id || "phase"} · ${phase.owner || "worker"} · ${phase.risk || "low"}`}</strong>
                <span>{phase.action || phase.command || "-"}</span>
              </div>)}
              {imessageReceivePlanForbiddenActions.slice(0, 3).map((item: string, index: number) => <div key={`imsg-plan-forbid-${index}`} className="compact-row warning">
                <strong>{item}</strong>
                <span>禁止动作</span>
              </div>)}
            </div>
          </div> : null}
          {imessageAcceptance.challengeText ? <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>iMessage 入站验收</h3><p>{shortPath(imessageAcceptancePath)}</p></div>
              <StatusPill value={imessageAcceptance.status || imessageChallenge.status || "unknown"} />
            </div>
            <div className="system-ops-mini-grid">
              <div><span>发送文本</span><strong>{imessageAcceptance.challengeText}</strong><small>{imessageAcceptance.blocker || imessageChallenge.status || "-"}</small></div>
              <div><span>允许发送方</span><strong>{imessageAllowedHandles.join(", ") || "-"}</strong><small>白名单入站</small></div>
              <div><span>有效期</span><strong>{imessageAcceptance.expiresInHours == null ? "-" : `${imessageAcceptance.expiresInHours}h`}</strong><small>{imessageAcceptance.isExpired ? "已过期" : "等待入站"}</small></div>
              <div><span>创建时间</span><strong>{String(imessageAcceptance.createdAt || "-").slice(0, 19)}</strong><small>freshness boundary</small></div>
              <div><span>过期时间</span><strong>{String(imessageAcceptance.expiresAt || "-").slice(0, 19)}</strong><small>{imessageAcceptance.canAutoRotateOnExpiry ? "到期可重建挑战" : "不自动重建"}</small></div>
              <div><span>Worker 自解</span><strong>{imessageAcceptance.workerCanSelfResolve ? "yes" : "no"}</strong><small>{imessageAcceptance.requiresHumanInbound ? "needs iPhone inbound" : "no human inbound"}</small></div>
            </div>
            <div className="system-ops-next-actions">
              <div className="compact-row warning">
                <strong>{imessageAcceptance.exactUserInstruction || "等待 iPhone 入站"}</strong>
                <span>{imessageAcceptance.freshnessBoundary || "必须是挑战创建后的新消息"}</span>
              </div>
              <div className="compact-row">
                <strong>{imessageAcceptance.verificationCommand || "node scripts/worker-imessage-inbound-challenge.cjs --dry-run --owner=worker"}</strong>
                <span>验收命令</span>
              </div>
              {imessageForbiddenActions.slice(0, 3).map((item: string, index: number) => <div key={`imsg-forbid-${index}`} className="compact-row warning">
                <strong>{item}</strong>
                <span>禁止动作</span>
              </div>)}
            </div>
          </div> : null}
          <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>Main Review 门控</h3><p>{shortPath(mainReview.reportPaths?.packetReport || autonomy.mainReviewPacketsReportPath)}</p></div>
              <div className="system-ops-review-head-actions">
                <StatusPill value={mainReview.summary?.waiting ? "pending" : (mainReview.summary?.total ? "ready" : "empty")} />
                <button type="button" className="secondary" disabled={busy === "review-consume"} onClick={() => void consumeMainReview()}>{busy === "review-consume" ? "消费中" : "执行审批消费"}</button>
              </div>
            </div>
            <div className="system-ops-mini-grid">
              <div><span>Total</span><strong>{mainReview.summary?.total == null ? "-" : mainReview.summary.total}</strong><small>{mainReview.summary?.highRisk == null ? "high -" : `${mainReview.summary.highRisk} high risk`}</small></div>
              <div><span>Waiting</span><strong>{mainReview.summary?.waiting == null ? "-" : mainReview.summary.waiting}</strong><small>Main decision required</small></div>
              <div><span>Shadow Ready</span><strong>{mainReview.summary?.shadowReady == null ? "-" : mainReview.summary.shadowReady}</strong><small>metadata-approved only</small></div>
            </div>
            <div className="system-ops-review-list">
              {reviewPackets.length ? reviewPackets.slice(0, 8).map((packet: any) => {
                const currentDecision = packet.decision || packet.decisionStatus || packet.consumptionStatus || "waiting";
                return <article key={packet.reviewId} className={`system-ops-review-card ${packet.riskLevel || "normal"}`}>
                  <div>
                    <strong>{packet.job?.name || packet.reviewId}</strong>
                    <span>{packet.reviewId} · {packet.riskLevel || "risk"} · {packet.diagnosis?.rootCause || "root-cause-unknown"}</span>
                    <small>{packet.workerShadowReportPath ? shortPath(packet.workerShadowReportPath) : (packet.recommendedDecision || "awaiting main decision")}</small>
                  </div>
                  <div className="system-ops-review-actions">
                    <StatusPill value={currentDecision} />
                    <button type="button" className="secondary" disabled={Boolean(packet.decision) || busy.startsWith(`review-${packet.reviewId}`)} onClick={() => void decideMainReview(packet.reviewId, "approve_shadow")}>只批准 shadow</button>
                    <button type="button" className="secondary" disabled={Boolean(packet.decision) || busy.startsWith(`review-${packet.reviewId}`)} onClick={() => void decideMainReview(packet.reviewId, "defer")}>暂缓</button>
                    <button type="button" className="secondary" disabled={Boolean(packet.decision) || busy.startsWith(`review-${packet.reviewId}`)} onClick={() => void decideMainReview(packet.reviewId, "reject")}>驳回</button>
                  </div>
                </article>;
              }) : <p className="muted">暂无 Main review packet。</p>}
            </div>
          </div>
          <div className="system-ops-report">
            <div className="panel-head">
              <div><h3>Final Delivery 审批</h3><p>{shortPath(finalApproval.reportPaths?.packetReport || autonomy.finalApprovalPackReportPath)}</p></div>
              <div className="system-ops-review-head-actions">
                <StatusPill value={finalApproval.summary?.waiting ? "pending" : (finalApproval.summary?.total ? "ready" : "empty")} />
                <button type="button" className="secondary" disabled={busy === "final-consume"} onClick={() => void consumeFinalApproval()}>{busy === "final-consume" ? "消费中" : "执行计划消费"}</button>
              </div>
            </div>
            <div className="system-ops-mini-grid">
              <div><span>Total</span><strong>{finalApproval.summary?.total == null ? "-" : finalApproval.summary.total}</strong><small>{finalApproval.summary?.highRisk == null ? "high -" : `${finalApproval.summary.highRisk} high risk`}</small></div>
              <div><span>Waiting</span><strong>{finalApproval.summary?.waiting == null ? "-" : finalApproval.summary.waiting}</strong><small>Main final decision required</small></div>
              <div><span>Plan Ready</span><strong>{finalApproval.summary?.planReady == null ? "-" : finalApproval.summary.planReady}</strong><small>local artifacts only</small></div>
              <div><span>Plan Dir</span><strong>{shortPath(finalApproval.reportPaths?.planDir || autonomy.finalApprovalPlanDir)}</strong><small>no cron mutation</small></div>
            </div>
            <div className="system-ops-review-list">
              {finalPackets.length ? finalPackets.slice(0, 8).map((packet: any) => {
                const currentDecision = packet.decision || packet.decisionStatus || packet.consumptionStatus || "waiting";
                return <article key={packet.finalReviewId} className={`system-ops-review-card ${packet.riskLevel || "high"}`}>
                  <div>
                    <strong>{packet.job?.name || packet.finalReviewId}</strong>
                    <span>{packet.finalReviewId} · {packet.riskLevel || "high"} · {packet.currentFailure?.category || "final-delivery"}</span>
                    <small>{packet.planMarkdownPath ? shortPath(packet.planMarkdownPath) : (packet.recommendedDecision || "awaiting final approval")}</small>
                  </div>
                  <div className="system-ops-review-actions">
                    <StatusPill value={currentDecision} />
                    <button type="button" className="secondary" disabled={Boolean(packet.decision) || busy.startsWith(`final-${packet.finalReviewId}`)} onClick={() => void decideFinalApproval(packet.finalReviewId, "approve_plan")}>批准生成计划</button>
                    <button type="button" className="secondary" disabled={Boolean(packet.decision) || busy.startsWith(`final-${packet.finalReviewId}`)} onClick={() => void decideFinalApproval(packet.finalReviewId, "defer")}>暂缓</button>
                    <button type="button" className="secondary" disabled={Boolean(packet.decision) || busy.startsWith(`final-${packet.finalReviewId}`)} onClick={() => void decideFinalApproval(packet.finalReviewId, "reject")}>驳回</button>
                  </div>
                </article>;
              }) : <p className="muted">暂无 Final Delivery approval packet。</p>}
            </div>
          </div>
          <div className="system-ops-risk-list">
            <div className="panel-head"><h3>风险与阻塞</h3><span>{risks.length}</span></div>
            {risks.length ? risks.map((risk: any, index: number) => <article key={`${risk.title}-${index}`} className={`system-ops-risk ${risk.level || "warn"}`}>
              <strong>{risk.title}</strong>
              <span>{risk.detail}</span>
            </article>) : <p className="muted">暂无需要升级的运维风险。</p>}
          </div>
        </section>
        <aside className="system-ops-side">
          <div className="system-ops-permissions">
            <h3>Worker 权限边界</h3>
            <div className="system-ops-permission-row"><span>Exec Node</span><strong>{permissions.exec?.node || "-"}</strong></div>
            <div className="system-ops-permission-row"><span>Security</span><strong>{permissions.exec?.security || "-"}</strong></div>
            <div className="system-ops-permission-row"><span>Ask</span><strong>{permissions.exec?.ask || "-"}</strong></div>
            <h4>自动允许</h4>
            <div className="agent-capability-row drawer">{(permissions.allowedLowRisk || []).map((item: string) => <span key={item}>{item}</span>)}</div>
            <h4>Main 审批</h4>
            <div className="agent-capability-row drawer warn">{(permissions.requiresMainApproval || []).map((item: string) => <span key={item}>{item}</span>)}</div>
          </div>
          <div className="system-ops-queue">
            <h3>被动运维队列</h3>
            {tasks.length ? tasks.slice(0, 8).map((task: any) => <div key={task.id} className="compact-row">
              <strong>{task.title}</strong>
              <span>{task.status} · {task.priority || "P2"} · {(task.updated_at || "").slice(0, 16)}</span>
            </div>) : <p className="muted">暂无 worker system_ops 运维任务。</p>}
          </div>
        </aside>
      </div>
      {message ? <div className="notice">{message}</div> : null}
    </>}
  </section>;
}

function ComputerUseCard({ status, auditRows, approvals }: { status: any; auditRows: any[]; approvals: any[] }) {
  const helper = status?.helper || {};
  const capabilities = status?.capabilities || {};
  const policy = status?.policy || {};
  const rows = Array.isArray(auditRows) ? auditRows.slice(0, 8) : [];
  const pending = Array.isArray(approvals) ? approvals.filter((row) => row.status === "pending").slice(0, 5) : [];
  const [wechatRecipient, setWechatRecipient] = useState("");
  const [wechatMessage, setWechatMessage] = useState("");
  const [wechatPreparing, setWechatPreparing] = useState(false);
  const [wechatPrepareResult, setWechatPrepareResult] = useState<any>(null);
  function approvalDetails(row: any) {
    if (!row?.details) return {};
    if (typeof row.details === "object") return row.details;
    try {
      return JSON.parse(String(row.details || "{}"));
    } catch {
      return {};
    }
  }
  async function prepareWechatApproval(e: FormEvent) {
    e.preventDefault();
    setWechatPreparing(true);
    setWechatPrepareResult(null);
    try {
      const result = await api("/api/computer-use/wechat/prepare", {
        method: "POST",
        body: JSON.stringify({ recipientName: wechatRecipient, message: wechatMessage }),
      });
      setWechatPrepareResult(result);
    } catch (err) {
      setWechatPrepareResult({ ok: false, error: err instanceof Error ? err.message : String(err) });
    } finally {
      setWechatPreparing(false);
    }
  }
  return <div className="panel">
    <h2>Computer Use</h2>
    <p className="muted">OpenClaw 原生本地桌面控制，不依赖 Codex App / Codex MCP。</p>
    {status?.permissionMismatch ? <div className="cron-warning inline">检测到 helper 权限上下文不一致：App bundle 与 raw binary 的 macOS 授权状态不同。建议以 App bundle 为准重新授权并重启 OpenClaw 运行上下文。</div> : null}
    <div className="source-health-grid">
      <div className={`source-health ${status?.ok ? "connected" : "warn"}`}>
        <strong>Driver</strong>
        <span>{status?.dependency || "unknown"}</span>
        <small>{status?.activeHelperIdentity || "helper"} · {status?.codexDependency === false ? "codexDependency=false" : "checking"}</small>
      </div>
      <div className={`source-health ${helper?.accessibility === "granted" ? "connected" : "warn"}`}>
        <strong>Accessibility</strong>
        <span>{helper?.accessibility || "unknown"}</span>
        <small>点击、输入、滚动需要授权</small>
      </div>
      <div className={`source-health ${helper?.screenCapture === "granted" ? "connected" : "warn"}`}>
        <strong>Screen</strong>
        <span>{helper?.screenCapture || "unknown"}</span>
        <small>截图和视觉观察需要授权</small>
      </div>
      <div className="source-health">
        <strong>Policy</strong>
        <span>{policy?.wechatAllowAutoSendCount ? `WeChat 白名单 ${policy.wechatAllowAutoSendCount}` : (policy?.configured ? "已配置" : "未配置")}</span>
        <small>{policy?.wechatDefaultMode || policy?.highRiskMode || "approval_required"}</small>
      </div>
    </div>
    <div className="mini-grid">
      <div><span>截图</span><strong>{capabilities.screenshot || "-"}</strong></div>
      <div><span>窗口</span><strong>{capabilities.windows || "-"}</strong></div>
      <div><span>指针</span><strong>{capabilities.pointer || "-"}</strong></div>
      <div><span>键盘</span><strong>{capabilities.keyboard || "-"}</strong></div>
      <div><span>微信发送</span><strong>{capabilities.wechatSend || "-"}</strong></div>
      <div><span>待审批</span><strong>{String(pending.length)}</strong></div>
    </div>
    <h3>微信外发准备</h3>
    <form className="inline-form stacked" onSubmit={(e) => void prepareWechatApproval(e)}>
      <input value={wechatRecipient} onChange={(e) => setWechatRecipient(e.target.value)} placeholder="收件人，例如 周增瑞" />
      <textarea value={wechatMessage} onChange={(e) => setWechatMessage(e.target.value)} placeholder="消息内容；本步骤只验证收件人并创建审批，不发送" rows={3} />
      <button type="submit" disabled={wechatPreparing || !wechatRecipient.trim() || !wechatMessage.trim()}>{wechatPreparing ? "验证中…" : "验证收件人并创建审批"}</button>
    </form>
    {wechatPrepareResult ? <div className={wechatPrepareResult.ok ? "cron-warning inline success" : "cron-warning inline"}>
      <strong>{wechatPrepareResult.ok ? "已创建待审批外发" : "验证失败，未创建审批"}</strong>
      <span>{wechatPrepareResult.ok ? `收件人：${wechatPrepareResult.prepare?.verifiedRecipientTitle || wechatRecipient}` : (wechatPrepareResult.prepare?.status || wechatPrepareResult.error || "recipient_verification_failed")}</span>
      <small>{wechatPrepareResult.prepare?.safeBehavior || "message_not_sent"}</small>
    </div> : null}
    {pending.length ? <><h3>待审批动作</h3><div className="compact-list">
      {pending.map((row: any) => {
        const details = approvalDetails(row);
        return <div key={row.id || `${row.requested_at}-${row.action}`} className="compact-row">
          <strong>{row.action || "computer_use"}</strong>
          <span>{details.verifiedRecipientTitle || details.recipientName || row.source || "approval"} · {(row.requested_at || "").slice(0, 19)}</span>
          {details.messageHash ? <small>hash {details.messageHash} · {details.safeBehavior || "message_not_sent"}</small> : null}
        </div>;
      })}
    </div></> : null}
    <h3>最近动作</h3>
    <div className="compact-list">
      {rows.length ? rows.map((row: any) => <div key={row.id || `${row.ts}-${row.action}`} className="compact-row">
        <strong>{row.action || "computer_use"}</strong>
        <span>{row.result || row.risk || "record"} · {(row.ts || "").slice(0, 19)}</span>
      </div>) : <p className="muted">暂无桌面动作审计记录。</p>}
    </div>
  </div>;
}

function SystemSourcesCard({ sources }: { sources: Record<string, any> }) {
  const rows = ["njx-knowledge", "memory", "wiki", "nas", "ima"].map((key) => ({ key, ...(sources?.[key] || {}) }));
  return <div className="panel"><h2>知识源状态</h2><div className="source-health-grid">
    {rows.map((source) => <div key={source.key} className={`source-health ${source.status || "unknown"}`}>
      <strong>{source.key.toUpperCase()}</strong>
      <span>{source.status || "unknown"}</span>
      <small>{source.path || source.note || source.error || "no detail"}</small>
    </div>)}
  </div></div>;
}

function SystemConnectorCard({ checks }: { checks: any[] }) {
  const rows = checks.filter((check) => ["plugins", "sandbox", "memory", "gateway", "agents"].includes(check.category));
  return <div className="panel"><h2>连接器与运行能力</h2><div className="table">
    {rows.length === 0 ? <p className="muted">暂无连接器状态</p> : rows.map((check) => <div className="row rich" key={`${check.category}-${check.name}`}>
      <div><strong>{check.name}</strong><span>{check.category}</span><small>{check.summary}</small></div>
      <StatusPill value={check.status || "unknown"} />
    </div>)}
  </div></div>;
}

function ReviewChecks({ checks }: { checks: any[] }) {
  return <div className="panel"><h2>配置评审</h2><div className="check-list">
    {checks.length === 0 ? <p className="muted">加载中</p> : checks.map((check) => <article className={`check ${check.status}`} key={`${check.category}-${check.name}`}>
      <strong>{check.name}</strong>
      <span>{check.category} / {check.status}</span>
      <p>{check.summary}</p>
    </article>)}
  </div></div>;
}

function AgentReview({ agents }: { agents: any[] }) {
  return <div className="panel"><h2>三代理工作区</h2><div className="table">
    {agents.map((agent) => <div className="row rich" key={agent.id}>
      <div><strong>{agent.id}</strong><span>{truthValue(agent.model)}</span><small>{truthValue(agent.workspace)}</small></div>
      <StatusPill value={agent.agentFile?.exists ? "ready" : "missing"} />
    </div>)}
  </div></div>;
}

function PageFrame({ title, subtitle, children, className }: { title: string; subtitle: string; children: React.ReactNode; className?: string }) {
  return <section className={`page ${className || ""}`.trim()}><header><div><h1>{title}</h1><p>{subtitle}</p></div></header>{children}</section>;
}

function StatusRow({ state }: { state: ApiState<unknown> }) {
  if (state.loading) return <div className="notice skeleton">Loading</div>;
  if (state.error) return <div className="notice error">{state.error}<button className="secondary" onClick={() => window.location.reload()}>重试</button></div>;
  return null;
}

function Metric({ label, value }: { label: string; value: string }) {
  return <div className="metric"><span>{label}</span><strong>{value}</strong></div>;
}

function DataCard({ title, data }: { title: string; data: unknown }) {
  return <div className="panel"><h2>{title}</h2><JsonPanel data={data} /></div>;
}

function ListCard({ title, rows }: { title: string; rows: any[] }) {
  return <div className="panel"><h2>{title}</h2><div className="table">
    {rows.length === 0 ? <p className="muted">暂无数据</p> : rows.map((row, i) => <div className="row" key={row.id || i}>
      <strong>{row.title || row.name || row.action || row.event_type || row.id}</strong>
      <span>{row.status || row.agent_id || row.requested_at || row.created_at || row.start_at}</span>
    </div>)}
  </div></div>;
}

function MiniGroup({ title, rows, onSelect }: { title: string; rows: any[]; onSelect?: (title: string, row: any) => void }) {
  return <section className="mini-group"><h3>{title} <small>{rows.length}</small></h3>{rows.length === 0 ? <span className="muted">无结果</span> : rows.slice(0, 6).map((row, i) => <button type="button" className="search-hit-button" key={row.id || i} onClick={() => onSelect?.(title, row)}>
    <strong>{row.title || row.name || row.summary || row.id}</strong>
    <small>{row.source || row.status || row.due_at || row.agent_id}</small>
  </button>)}</section>;
}

function JsonPanel({ data }: { data: unknown }) {
  const text = useMemo(() => JSON.stringify(data || {}, null, 2), [data]);
  return <pre className="json">{text}</pre>;
}

function StatusPill({ value }: { value: string }) {
  return <span className={`pill ${value}`}>{value}</span>;
}

function StatusBar({ live }: { live: { snapshot: any; connected: boolean } }) {
  const gateway = live.snapshot?.gateway || {};
  const gatewayStatus = gateway.status || "checking";
  const gatewayTitle = [
    `Gateway: ${gatewayStatus}`,
    gateway.source ? `source=${gateway.source}` : "",
    gateway.checkedAt ? `checked=${gateway.checkedAt}` : "",
    typeof gateway.durationMs === "number" ? `duration=${gateway.durationMs}ms` : "",
    gateway.nextCheckAt ? `next=${gateway.nextCheckAt}` : "",
    gateway.error ? `error=${gateway.error}` : "",
  ].filter(Boolean).join(" · ");
  return <footer className="statusbar">
    <span>SSE: {live.connected ? "connected" : "checking"}</span>
    <span title={gatewayTitle}>Gateway: {gatewayStatus}</span>
    <span>Updated: {live.snapshot?.ts || "-"}</span>
  </footer>;
}

function groupBySource(rows: any[]) {
  const groups = new Map<string, any[]>();
  for (const row of rows) groups.set(row.source, [...(groups.get(row.source) || []), row]);
  return [...groups.entries()];
}

function statusColor(status: string) {
  if (status === "running") return "#1d4ed8";
  if (status === "completed") return "#0f766e";
  if (status === "failed" || status === "gateway_unavailable") return "#b42318";
  if (status === "pending_approval") return "#d97706";
  return "#94a3b8";
}

function formatLocalDate(date: Date) {
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function formatLocalDateTimeInput(date: Date) {
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${formatLocalDate(date)}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function toDateTimeLocalValue(value?: string) {
  const raw = String(value || "");
  const match = raw.match(/^(\d{4}-\d{2}-\d{2})[T\s](\d{2}:\d{2})/);
  return match ? `${match[1]}T${match[2]}` : "";
}

function formatShortDateTime(value?: string | null) {
  const raw = String(value || "");
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})[T\s](\d{2}):(\d{2})/);
  return match ? `${match[2]}/${match[3]} ${match[4]}:${match[5]}` : raw.slice(0, 16);
}

function importActionLabel(action: ReminderImportItem["action"]) {
  if (action === "create") return "创建";
  if (action === "update") return "更新";
  if (action === "duplicate") return "重复";
  return "跳过";
}

function todoSyncStatusKey(status?: string | null) {
  const key = String(status || "pending").toLowerCase();
  if (["synced", "pending", "conflict", "error"].includes(key)) return key;
  return "pending";
}

function todoSyncStatusLabel(status?: string | null) {
  const key = todoSyncStatusKey(status);
  if (key === "synced") return "提醒已同步";
  if (key === "conflict") return "同步冲突";
  if (key === "error") return "同步失败";
  return "待推送";
}

function todoPlanShortLabel(row: any) {
  const type = todoPlanType(row);
  if (type === "life") return "人生";
  if (type === "work") return "工作";
  return "待办";
}

function planTodoCounts(rows: any[]) {
  return rows.reduce((acc, row) => {
    acc[todoPlanType(row)] += 1;
    return acc;
  }, { personal: 0, life: 0, work: 0 } as Record<TodoPlanType, number>);
}

function defaultTodoDueAt() {
  const date = new Date();
  date.setMinutes(0, 0, 0);
  date.setHours(date.getHours() + 1);
  return formatLocalDateTimeInput(date);
}

function localDate(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return new Date();
  return new Date(year, month - 1, day);
}

function startOfWeek(date: Date) {
  const out = new Date(date);
  const offset = (out.getDay() + 6) % 7;
  out.setDate(out.getDate() - offset);
  return out;
}

function endOfWeek(date: Date) {
  const out = startOfWeek(date);
  out.setDate(out.getDate() + 6);
  return out;
}

function calendarRange(mode: CalendarMode, anchorKey: string) {
  const anchor = localDate(anchorKey);
  if (mode === "day") {
    const day = formatLocalDate(anchor);
    return { start: day, end: day, label: `${day} 日` };
  }
  if (mode === "week") {
    const start = startOfWeek(anchor);
    const end = endOfWeek(anchor);
    return { start: formatLocalDate(start), end: formatLocalDate(end), label: `${formatLocalDate(start)} 本周` };
  }
  if (mode === "year") {
    const start = new Date(anchor.getFullYear(), 0, 1);
    const end = new Date(anchor.getFullYear(), 11, 31);
    return { start: formatLocalDate(start), end: formatLocalDate(end), label: `${anchor.getFullYear()} 年` };
  }
  const first = new Date(anchor.getFullYear(), anchor.getMonth(), 1);
  const last = new Date(anchor.getFullYear(), anchor.getMonth() + 1, 0);
  const start = startOfWeek(first);
  const end = endOfWeek(last);
  return { start: formatLocalDate(start), end: formatLocalDate(end), label: `${anchor.getFullYear()} 年 ${anchor.getMonth() + 1} 月` };
}

function calendarMonths(mode: CalendarMode, anchorKey: string, selectedDate: string): CalendarMonth[] {
  const anchor = localDate(anchorKey);
  if (mode === "day") {
    const day = formatLocalDate(anchor);
    return [{ key: `day-${day}`, title: `${anchor.getFullYear()} 年 ${anchor.getMonth() + 1} 月 ${anchor.getDate()} 日`, days: [calendarDay(day, true, selectedDate)] }];
  }
  if (mode === "week") {
    const range = calendarRange(mode, anchorKey);
    const days = daysInRange(range.start, range.end).map((date) => calendarDay(date, true, selectedDate));
    return [{ key: `week-${range.start}`, title: "本周", days }];
  }
  if (mode === "year") {
    return Array.from({ length: 12 }, (_, index) => buildMonth(anchor.getFullYear(), index, selectedDate));
  }
  return [buildMonth(anchor.getFullYear(), anchor.getMonth(), selectedDate)];
}

function buildMonth(year: number, month: number, selectedDate: string): CalendarMonth {
  const first = new Date(year, month, 1);
  const last = new Date(year, month + 1, 0);
  const start = startOfWeek(first);
  const end = endOfWeek(last);
  const days = daysInRange(formatLocalDate(start), formatLocalDate(end)).map((date) => {
    const parsed = localDate(date);
    return calendarDay(date, parsed.getMonth() === month, selectedDate);
  });
  return { key: `${year}-${String(month + 1).padStart(2, "0")}`, title: `${month + 1} 月`, days };
}

function calendarDay(date: string, inPeriod: boolean, selectedDate: string): CalendarDay {
  const parsed = localDate(date);
  const selected = localDate(selectedDate);
  const sameSelectedMonth = parsed.getFullYear() === selected.getFullYear() && parsed.getMonth() === selected.getMonth();
  return {
    key: date,
    label: inPeriod || sameSelectedMonth ? String(parsed.getDate()) : `${parsed.getMonth() + 1}/${parsed.getDate()}`,
    inPeriod,
    isToday: date === formatLocalDate(new Date()),
  };
}

function daysInRange(startKey: string, endKey: string) {
  const out: string[] = [];
  const current = localDate(startKey);
  const end = localDate(endKey);
  while (current.getTime() <= end.getTime()) {
    out.push(formatLocalDate(current));
    current.setDate(current.getDate() + 1);
  }
  return out;
}

function dateInRange(date: string, start: string, end: string) {
  return Boolean(date && date >= start && date <= end);
}

function mergeRowsById(primaryRows: any[], secondaryRows: any[]) {
  const rows = new Map<string, any>();
  for (const row of primaryRows || []) {
    const id = String(row?.id || "");
    if (id) rows.set(id, row);
  }
  for (const row of secondaryRows || []) {
    const id = String(row?.id || "");
    if (id) rows.set(id, row);
  }
  return [...rows.values()];
}

function applyDueAtOverride(row: any, overrides: Record<string, string | null>) {
  const id = String(row?.id || "");
  if (!id || !Object.prototype.hasOwnProperty.call(overrides, id)) return row;
  return { ...row, due_at: overrides[id] };
}

function groupByDate(rows: any[], primaryKey: string, fallbackKey?: string) {
  const groups = new Map<string, any[]>();
  for (const row of rows) {
    const key = String(row[primaryKey] || (fallbackKey ? row[fallbackKey] : "") || "").slice(0, 10);
    if (!key) continue;
    groups.set(key, [...(groups.get(key) || []), row]);
  }
  return groups;
}

function indexByDate(rows: CalendarHoliday[]) {
  const index = new Map<string, CalendarHoliday>();
  for (const row of rows) if (row.date) index.set(row.date, row);
  return index;
}

function holidayChip(holiday: CalendarHoliday | undefined, mode: CalendarMode) {
  if (!holiday) return null;
  if (holiday.isHoliday) return <span className="calendar-pill holiday-pill">{holiday.name || "节假日"}</span>;
  if (holiday.isMakeupWorkday) return <span className="calendar-pill makeup-pill">{holiday.name || "补班"}</span>;
  if (holiday.type === "weekend" && mode !== "year") return <span className="calendar-pill weekend-pill">周末</span>;
  return null;
}

function holidaySummary(holiday: CalendarHoliday | undefined) {
  if (!holiday) return <strong>普通日</strong>;
  if (holiday.isHoliday) return <strong className="holiday-summary holiday">{holiday.name || "节假日"}</strong>;
  if (holiday.isMakeupWorkday) return <strong className="holiday-summary makeup">{holiday.name || "调休补班"}</strong>;
  if (holiday.type === "weekend") return <strong className="holiday-summary weekend">周末</strong>;
  return <strong>工作日</strong>;
}

function isTodoDone(row: any) {
  return ["done", "completed"].includes(String(row?.status || "").toLowerCase());
}

function todoGroupLabel(row: any, key: TodoGroupKey) {
  if (key === "status") return row.status || "open";
  if (key === "priority") return row.priority || "P2";
  if (key === "list_name") return row.list_name || row.source || "默认分组";
  const due = String(row.due_at || "").slice(0, 10);
  if (!due) return "无截止时间";
  const today = formatLocalDate(new Date());
  if (due < today) return "已逾期";
  if (due === today) return "今天";
  const date = localDate(due);
  const now = localDate(today);
  if (date.getFullYear() === now.getFullYear() && date.getMonth() === now.getMonth()) return "本月";
  return "未来";
}

function shortPath(value?: string) {
  if (!value) return "-";
  return value.replace("/Users/njx/openclaw_data", "openclaw_data");
}
